"use client";
import React, { useEffect, useRef, useState, useCallback } from "react";
import { gsap } from "gsap";
import { Draggable } from "gsap/Draggable";
import { InertiaPlugin } from "gsap/InertiaPlugin";
import MaskedContainer from "@/components/DraggableCanvas/MaskedContainer";
import DragCursor from "@/components/DraggableCanvas/DragCursor";

gsap.registerPlugin(Draggable, InertiaPlugin);

export default function DraggableVideo() {
  const videoRef = useRef(null);
  const [isVideoReady, setIsVideoReady] = useState(false);
  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });
  const [isHoveringDraggable, setIsHoveringDraggable] = useState(false);
  const [containerPositions, setContainerPositions] = useState({
    large: { x: 0, y: 0 },
    medium: { x: 0, y: 0 },
    small: { x: 0, y: 0 },
    extra1: { x: 0, y: 0 },
    extra2: { x: 0, y: 0 },
    extra3: { x: 0, y: 0 }
  });

  useEffect(() => {
    const video = videoRef.current;

    if (!video) return;

    // Set canvas size
    const updateCanvasSize = () => {
      setCanvasSize({
        width: window.innerWidth,
        height: window.innerHeight,
      });
    };

    updateCanvasSize();
    window.addEventListener("resize", updateCanvasSize);

    // Video event handlers
    const handleVideoCanPlay = () => {
      setIsVideoReady(true);
    };

    const handleVideoError = () => {
      console.error("Video failed to load");
      setIsVideoReady(false);
    };

    // Add video event listeners
    video.addEventListener("canplay", handleVideoCanPlay);
    video.addEventListener("error", handleVideoError);

    // Force video to load
    video.load();

    return () => {
      window.removeEventListener("resize", updateCanvasSize);
      video.removeEventListener("canplay", handleVideoCanPlay);
      video.removeEventListener("error", handleVideoError);
    };
  }, []);


  const handlePositionUpdate = useCallback((size, position) => {
    setContainerPositions(prev => ({
      ...prev,
      [size]: position
    }));
  }, []);

  const handleHoverChange = useCallback((isHovering) => {
    setIsHoveringDraggable(isHovering);
  }, []);

  return (
    <div className="relative w-full h-screen overflow-hidden  bg-black">
        <DragCursor isHoveringDraggable={isHoveringDraggable}/>
        <div className="absolute w-full h-full inset-0  z-10"></div>
      {/* Hidden video element - single source for all masks */}
      <video
        ref={videoRef}
        src="/assets/videos/draggable-video.mp4"
        className="opacity-0 absolute top-0 left-0 w-full h-full object-cover"
        autoPlay
        muted
        loop
        playsInline
        preload="auto"
        crossOrigin="anonymous"
      />


      {isVideoReady && (
        <MaskedContainer
          size="large"
          initialPosition={{ x: 0, y: 0 }}
          className="w-[60vw] h-[35vw] absolute top-[10vh] left-[10vw]"
          video={videoRef.current}
          canvasSize={canvasSize}
          onPositionUpdate={handlePositionUpdate}
          onHoverChange={handleHoverChange}
        />
      )}

      {isVideoReady && (
        <MaskedContainer
          size="medium"
          initialPosition={{ x: 0, y: 0 }}
          className="w-[17vw] h-[9vw] absolute top-[5%] left-[5vw]"
          video={videoRef.current}
          canvasSize={canvasSize}
          onPositionUpdate={handlePositionUpdate}
          onHoverChange={handleHoverChange}
        />
      )}



      {isVideoReady && (
        <MaskedContainer
          size="extra1"
          initialPosition={{ x: 0, y: 0 }}
          className="w-[35vw] h-[19vw] absolute top-[5vh] right-[5vw]"
          video={videoRef.current}
          canvasSize={canvasSize}
          onPositionUpdate={handlePositionUpdate}
          onHoverChange={handleHoverChange}
        />
      )}

      {isVideoReady && (
        <MaskedContainer
          size="extra2"
          initialPosition={{ x: 0, y: 0 }}
          className="w-[38vw] h-[22vw] absolute top-[50vh] left-[5vw]"
          video={videoRef.current}
          canvasSize={canvasSize}
          onPositionUpdate={handlePositionUpdate}
          onHoverChange={handleHoverChange}
        />
      )}

      {isVideoReady && (
        <MaskedContainer
          size="extra3"
          initialPosition={{ x: 0, y: 0 }}
          className="w-[25vw] h-[14vw] absolute bottom-[20%] right-[10vw]"
          video={videoRef.current}
          canvasSize={canvasSize}
          onPositionUpdate={handlePositionUpdate}
          onHoverChange={handleHoverChange}
        />
      )}
        {isVideoReady && (
        <MaskedContainer
          size="small"
          initialPosition={{ x: 0, y: 0 }}
          className="w-[22vw] h-[12vw] absolute bottom-[15vh] left-1/2 -translate-x-1/2"
          video={videoRef.current}
          canvasSize={canvasSize}
          onPositionUpdate={handlePositionUpdate}
          onHoverChange={handleHoverChange}
        />
      )}
    </div>
  );
}

"use client";

import React, {
 createContext,
 useContext,
 useEffect,
 useId,
 useMemo,
 useRef,
 useState,
} from"react";
import gsap from"gsap";
import ChevronBird from"../ChevronBird/ChevronBird";

const FAQContext = createContext(null);
const FAQGroupContext = createContext(null);

const useFAQContext = () => {
 const context = useContext(FAQContext);

 if (!context) {
 throw new Error("FAQTitle and FAQContent must be used inside FAQWrapper.");
 }

 return context;
};

export function FAQGroup({
 children,
 allowMultiple = false,
 defaultOpenItems = [],
 value,
 onChange,
}) {
 const isControlled = Array.isArray(value);
 const [internalOpenItems, setInternalOpenItems] = useState(defaultOpenItems);

 const openItems = isControlled ? value : internalOpenItems;

 const toggleItem = (itemId) => {
 const next = (() => {
 const isOpen = openItems.includes(itemId);

 if (allowMultiple) {
 return isOpen
 ? openItems.filter((id) => id !== itemId)
 : [...openItems, itemId];
 }

 return isOpen ? [] : [itemId];
 })();

 if (!isControlled) {
 setInternalOpenItems(next);
 }

 onChange?.(next);
 };

 const contextValue = useMemo(
 () => ({
 allowMultiple,
 openItems,
 toggleItem,
 }),
 [allowMultiple, openItems]
 );

 return (
 <FAQGroupContext.Provider value={contextValue}>
 {children}
 </FAQGroupContext.Provider>
 );
}

export function FAQWrapper({
 children,
 className ="",
 titleClassName ="",
 contentClassName ="",
 iconClassName ="",
 iconSize = 14,
 iconStrokeWidth = 10,
 duration = 0.45,
 defaultOpen = false,
 controlledOpen,
 onToggle,
 itemId,
}) {
 const group = useContext(FAQGroupContext);

 const generatedId = useId();
 const resolvedItemId = itemId ?? generatedId;

 const isStandaloneControlled = typeof controlledOpen ==="boolean";
 const [internalOpen, setInternalOpen] = useState(defaultOpen);

 const isOpen = group
 ? group.openItems.includes(resolvedItemId)
 : isStandaloneControlled
 ? controlledOpen
 : internalOpen;

 const contentOuterRef = useRef(null);
 const contentInnerRef = useRef(null);

 const contentId = useId();
 const buttonId = useId();

 const handleToggle = () => {
 if (group) {
 group.toggleItem(resolvedItemId);
 onToggle?.(!isOpen);
 return;
 }

 if (isStandaloneControlled) {
 onToggle?.(!controlledOpen);
 return;
 }

 setInternalOpen((prev) => {
 const next = !prev;
 onToggle?.(next);
 return next;
 });
 };

 const handleWrapperClick = (e) => {
 const isInteractive = e.target.closest("a, button, input, textarea, select");
 if (isInteractive) return;

 handleToggle();
 };

 const handleKeyDown = (e) => {
 if (e.key ==="Enter" || e.key ==="") {
 e.preventDefault();
 handleToggle();
 }
 };

 useEffect(() => {
 if (!contentOuterRef.current || !contentInnerRef.current) return;

 const outer = contentOuterRef.current;
 const inner = contentInnerRef.current;

 gsap.killTweensOf([outer, inner]);

 if (isOpen) {
 gsap.set(outer, {
 display:"block",
 overflow:"hidden",
 });

 gsap.fromTo(
 outer,
 { height: 0 },
 {
 height: inner.offsetHeight,
 duration,
 ease:"power3.out",
 onComplete: () => {
 gsap.set(outer, {
 height:"auto",
 overflow:"visible",
 });
 },
 }
 );
 } else {
 gsap.set(outer, { overflow:"hidden" });

 gsap.to(outer, {
 height: 0,
 duration,
 ease:"power3.out",
 onComplete: () => {
 gsap.set(outer, { display:"none" });
 },
 });
 }
 }, [isOpen, duration]);

 const value = {
 isOpen,
 contentOuterRef,
 contentInnerRef,
 contentId,
 buttonId,
 titleClassName,
 contentClassName,
 iconClassName,
 iconSize,
 iconStrokeWidth,
 };

 return (
 <FAQContext.Provider value={value}>
 <div
 className={`cursor-pointer ${className}`}
 role="button"
 tabIndex={0}
 aria-expanded={isOpen}
 aria-controls={contentId}
 id={buttonId}
 onClick={handleWrapperClick}
 onKeyDown={handleKeyDown}
 >
 {children}
 </div>
 </FAQContext.Provider>
 );
}

export function FAQTitle({
 children,
 className ="",
 showIcon = true,
 iconPosition ="right",
}) {
 const {
 isOpen,
 titleClassName,
 iconClassName,
 iconSize,
 iconStrokeWidth,
 } = useFAQContext();

 const icon = showIcon ? (
 <div className={`shrink-0 ${iconClassName}`}>
 <ChevronBird
 isActive={isOpen}
 size={iconSize}
 strokeWidth={iconStrokeWidth}
 />
 </div>
 ) : null;

 return (
 <div
 className={`flex w-full items-start justify-between gap-6 ${titleClassName} ${className}`}
 >
 {iconPosition ==="left" ? (
 <>
 {icon}
 <div className="flex-1">{children}</div>
 </>
 ) : (
 <>
 <div className="flex-1">{children}</div>
 {icon}
 </>
 )}
 </div>
 );
}

export function FAQContent({
