'use client'
import { useTexture } from"@react-three/drei";
import { useFrame } from"@react-three/fiber";
import { easing } from"maath";
import { usePage } from"./PageContext";
import { useEffect, useMemo, useRef, useState } from"react";
import {
 Bone,
 BoxGeometry,
 Color,
 Float32BufferAttribute,
 MathUtils,
 MeshStandardMaterial,
 Skeleton,
 SkinnedMesh,
 SRGBColorSpace,
 Uint16BufferAttribute,
 Vector3,
} from"three";
import { degToRad } from"three/src/math/MathUtils.js";

/**
 * CONFIG CONSTANTS - Adjust these to customize the book appearance and animation
 */
const EASING_FACTOR = 0.5; // Controls the speed of page rotation easing (lower = slower)
const EASING_FACTOR_FOLD = 0.3; // Controls the speed of page fold animation
const INSIDE_CURVE_STRENGTH = 0.18; // How much the inside of the page curves when opened
const OUTSIDE_CURVE_STRENGTH = 0.05; // How much the outside edges curve
const TURNING_CURVE_STRENGTH = 0.09; // Curve strength during page turning animation

const PAGE_WIDTH = 1.28; // Width of a single page
const PAGE_HEIGHT = 1.71; // Height of a single page (4:3 aspect ratio)
const PAGE_DEPTH = 0.003; // Thickness of paper
const PAGE_SEGMENTS = 30; // Number of bone segments (more = more flexible, but slower)
const SEGMENT_WIDTH = PAGE_WIDTH / PAGE_SEGMENTS;

/**
 * GEOMETRY SETUP
 * Creates a segmented geometry that can be deformed by skeleton bones
 * Each segment is controlled by 2 bones for smooth deformation
 */
const pageGeometry = new BoxGeometry(
 PAGE_WIDTH,
 PAGE_HEIGHT,
 PAGE_DEPTH,
 PAGE_SEGMENTS,
 2
);

// Translate geometry so rotation happens from the left edge
pageGeometry.translate(PAGE_WIDTH / 2, 0, 0);

// Setup skin weights and indices for skeletal animation
const position = pageGeometry.attributes.position;
const vertex = new Vector3();
const skinIndexes = [];
const skinWeights = [];

for (let i = 0; i < position.count; i++) {
 vertex.fromBufferAttribute(position, i);
 const x = vertex.x;

 // Each vertex is influenced by 2 adjacent bones
 const skinIndex = Math.max(0, Math.floor(x / SEGMENT_WIDTH));
 let skinWeight = (x % SEGMENT_WIDTH) / SEGMENT_WIDTH;

 // Store bone influences (up to 4 per vertex, we use 2)
 skinIndexes.push(skinIndex, skinIndex + 1, 0, 0);
 skinWeights.push(1 - skinWeight, skinWeight, 0, 0);
}

pageGeometry.setAttribute(
"skinIndex",
 new Uint16BufferAttribute(skinIndexes, 4)
);
pageGeometry.setAttribute(
"skinWeight",
 new Float32BufferAttribute(skinWeights, 4)
);

// Base materials for pages
const whiteColor = new Color("white");
const emissiveColor = new Color("orange");

const pageMaterials = [
 new MeshStandardMaterial({ color: whiteColor }),
 new MeshStandardMaterial({ color:"#111" }),
 new MeshStandardMaterial({ color: whiteColor }),
 new MeshStandardMaterial({ color: whiteColor }),
];

/**
 * Helper function to generate page pairs from image array
 * Creates front/back pairs: [0,1], [2,3], [4,5], etc.
 */
const generatePages = (imageArray) => {
 if (!imageArray || imageArray.length === 0) {
 return [];
 }

 const pages = [
 {
 front: imageArray[0],
 back: imageArray[1] || imageArray[0],
 },
 ];

 for (let i = 2; i < imageArray.length - 1; i += 2) {
 pages.push({
 front: imageArray[i],
 back: imageArray[i + 1],
 });
 }

 if (imageArray.length % 2 === 1) {
 pages.push({
 front: imageArray[imageArray.length - 1],
 back: imageArray[0],
 });
 }

 return pages;
};

/**
 * Preload textures for better performance
 */
const preloadTextures = (pages, pathPattern) => {
 pages.forEach((page) => {
 useTexture.preload(`${pathPattern}/${page.front}.png`);
 useTexture.preload(`${pathPattern}/${page.back}.png`);
 });
};

/**
 * PAGE COMPONENT
 * Represents a single page in the book with skinned mesh deformation
 *  * ANIMATION LOGIC:
 * - Uses skeleton with 31 bones along the page width
 * - Each bone rotates based on whether the page is opened
 * - Inner bones curve more (3D effect), outer bones curve less
 * - During turning, bones follow a sine wave for smooth animation
 */
const Page = ({  number,  front,  back,  page,  opened,  bookClosed,
 pathPattern,
 pages,
 ...props }) => {
 const frontPath = `${pathPattern}/${front}.png`;
 const backPath = `${pathPattern}/${back}.png`;

 const [picture, picture2] = useTexture([frontPath, backPath]);
 picture.colorSpace = picture2.colorSpace = SRGBColorSpace;

 const group = useRef();
 const turnedAt = useRef(0);
 const lastOpened = useRef(opened);
 const skinnedMeshRef = useRef();

 /**
 * Create the skeletal mesh for this page
 * - Creates 31 bones in a chain
 * - Attaches them hierarchically so rotation cascades
 * - Wraps geometry in skeleton for deformation
 */
 const manualSkinnedMesh = useMemo(() => {
 const bones = [];
  // Create bone chain
 for (let i = 0; i <= PAGE_SEGMENTS; i++) {
 let bone = new Bone();
 bones.push(bone);
  if (i === 0) {
 bone.position.x = 0; // Root bone at spine
 } else {
 bone.position.x = SEGMENT_WIDTH; // Each subsequent bone positioned relative to parent
 }
  if (i > 0) {
 bones[i - 1].add(bone); // Attach to parent bone
 }
 }

 const skeleton = new Skeleton(bones);

 // Materials: 4 base materials + 2 textured materials (front and back)
 const materials = [
 ...pageMaterials,
 new MeshStandardMaterial({
 color: whiteColor,
 map: picture,
 roughness: 0.1,
 emissive: emissiveColor,
 emissiveIntensity: 0,
 }),
 new MeshStandardMaterial({
 color: whiteColor,
 map: picture2,
 roughness: 0.1,
 emissive: emissiveColor,
 emissiveIntensity: 0,
 }),
 ];

 const mesh = new SkinnedMesh(pageGeometry, materials);
 mesh.frustumCulled = false;
 mesh.add(skeleton.bones[0]);
 mesh.bind(skeleton); // Bind skeleton to mesh
  return mesh;
 }, [picture, picture2]);

 /**
 * ANIMATION LOOP
 * Updates bone rotations each frame to create page flip effect
 */
 useFrame((_, delta) => {
 if (!skinnedMeshRef.current) return;

 // Highlight page on hover by increasing emissive intensity
 // const emissiveIntensity = highlighted ? 0.22 : 0;
 // skinnedMeshRef.current.material[4].emissiveIntensity =
 // skinnedMeshRef.current.material[5].emissiveIntensity = MathUtils.lerp(
 // skinnedMeshRef.current.material[4].emissiveIntensity,
 // emissiveIntensity,
 // 0.1
 // );

 // Track when page opened state changed for animation timing
 if (lastOpened.current !== opened) {
 turnedAt.current = +new Date();
 lastOpened.current = opened;
 }

 // Calculate animation progress (0 to 1, then sin for smooth curve)
 let turningTime = Math.min(400, new Date() - turnedAt.current) / 400;
 turningTime = Math.sin(turningTime * Math.PI);

 // Target rotation: opened = -90°, closed = +90°
 let targetRotation = opened ? -Math.PI / 2 : Math.PI / 2;
  // Add slight extra rotation based on page number (pages fan out slightly)
 if (!bookClosed) {
 targetRotation += degToRad(number * 0.8);
 }

 /**
 * BONE ANIMATION CALCULATION
 * Each bone along the page rotates differently:
 * - Inside bones (0-8): Follow sin curve for inside curl effect
 * - Outside bones (8+): Follow cos curve for outside edge effect
 * - All bones smoothly interpolate to target rotation using dampAngle
 */
 const bones = skinnedMeshRef.current.skeleton.bones;
 for (let i = 0; i < bones.length; i++) {
 const target = i === 0 ? group.current : bones[i];

 // Inner curve: creates 3D curl effect on the inside
 const insideCurveIntensity = i < 8 ? Math.sin(i * 0.2 + 0.25) : 0;
  // Outer curve: pages don't rotate as much at the edges
 const outsideCurveIntensity = i >= 8 ? Math.cos(i * 0.3 + 0.09) : 0;
  // Turning animation: smooth wave during the page turn
 const turningIntensity =
 Math.sin(i * Math.PI * (1 / bones.length)) * turningTime;

 // Combine all rotation influences
 let rotationAngle =
 INSIDE_CURVE_STRENGTH * insideCurveIntensity * targetRotation -
 OUTSIDE_CURVE_STRENGTH * outsideCurveIntensity * targetRotation +
 TURNING_CURVE_STRENGTH * turningIntensity * targetRotation;

 // Fold rotation: subtle X-axis rotation for paper fold effect
 let foldRotationAngle = degToRad(Math.sign(targetRotation) * 2);

 // When book is closed, only root bone rotates
 if (bookClosed) {
 if (i === 0) {
 rotationAngle = targetRotation;
 foldRotationAngle = 0;
 } else {
 rotationAngle = 0;
 foldRotationAngle = 0;
 }
 }

 // Smoothly ease bones to target rotation
 easing.dampAngle(
 target.rotation,
"y",
 rotationAngle,
 EASING_FACTOR,
 delta
 );

 // Add fold effect to middle/end bones during turning
 const foldIntensity =
 i > 8
 ? Math.sin(i * Math.PI * (1 / bones.length) - 0.5) * turningTime
 : 0;
 easing.dampAngle(
 target.rotation,
"x",
 foldRotationAngle * foldIntensity,
 EASING_FACTOR_FOLD,
 delta
 );
 }
 });

 const { setPage } = usePage();
// const [highlighted, setHighlighted] = useState(false);
// useCursor(highlighted);

 return (
 <group
 {...props}
 ref={group}
 // onPointerEnter={(e) => {
 // e.stopPropagation();
 // setHighlighted(true);
 // }}
 // onPointerLeave={(e) => {
 // e.stopPropagation();
 // setHighlighted(false);
 // }}
 onClick={(e) => {
 e.stopPropagation();
 setPage(opened ? number : number + 1);
 // setHighlighted(false);
 }}
 >
 <primitive
 object={manualSkinnedMesh}
 ref={skinnedMeshRef}
 // Stack pages with slight depth offset
 position-z={-number * PAGE_DEPTH + page * PAGE_DEPTH}
 />
 </group>
 );
};

/**
 * BOOK COMPONENT
 * Main book component that orchestrates page animation
 *  * ANIMATION FLOW:
 * 1. User clicks to change page number in PageContext
 * 2. delayedPage state animates one page at a time toward target
 * 3. Each page renders and receives updated page/opened props
 * 4. Pages animate their bones based on opened state
 */
export const Book = ({  images = [],
 pathPattern ="/assets/nature",
 ...props }) => {
 const { page } = usePage();
 const [delayedPage, setDelayedPage] = useState(page);

 // Generate pages from image array
 const pages = useMemo(() => generatePages(images), [images]);

 // Preload textures
 useEffect(() => {
 if (pages.length > 0) {
 preloadTextures(pages, pathPattern);
 }
 }, [pages, pathPattern]);

 /**
 * PAGE ANIMATION SEQUENCING
 * Animates delayedPage toward target page one page at a time
 * This creates the sequential page-by-page animation
 */
 useEffect(() => {
 let timeout;
 const goToPage = () => {
 setDelayedPage((delayedPage) => {
 if (page === delayedPage) {
 return delayedPage;
 } else {
 // Faster animation for large jumps, slower for single pages
 timeout = setTimeout(
 () => {
 goToPage();
 },
 Math.abs(page - delayedPage) > 2 ? 50 : 150
 );
  if (page > delayedPage) {
 return delayedPage + 1;
 }
 if (page < delayedPage) {
 return delayedPage - 1;
 }
 }
 });
 };
 goToPage();
 return () => {
 clearTimeout(timeout);
 };
 }, [page]);

 return (
 <group {...props} rotation-y={-Math.PI / 2} rotation-x={-0.7} >
 {pages.map((pageData, index) => (
 <Page
 key={index}
 page={delayedPage}
 number={index}
 opened={delayedPage > index}
 bookClosed={delayedPage === 0 || delayedPage === pages.length}
 pathPattern={pathPattern}
 pages={pages}
 {...pageData}
 />
 ))}
 </group>
 );
};

"use client";

import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from"react";
import gsap from"gsap";
import { Draggable } from"gsap/Draggable";
import { ArrowLeft, ArrowRight } from"lucide-react";
import"./RingGallery.css";

gsap.registerPlugin(Draggable);

const RingGallery = ({
 items = [],
 itemWidth = 700,
 itemHeight = 300,
 radius = 500,
 gap = 0,
 dragSensitivity = 0.35,
 momentum = 1,
 friction = 0.95,
 snap = true,
 className ="",
 renderItem,
 showNavigation = true,
 showDots = true,
 autoPlay = false,
 autoPlayInterval = 3000,
 pauseOnHover = true,
}) => {
 const containerRef = useRef(null);
 const ringRef = useRef(null);
 const draggerRef = useRef(null);
 const itemRefs = useRef([]);
 const momentumFrameRef = useRef(null);
 const autoplayRef = useRef(null);
 const velocityRef = useRef(0);
 const lastXRef = useRef(0);
 const isHoveredRef = useRef(false);
 const currentStepRef = useRef(0);

 const [activeIndex, setActiveIndex] = useState(0);

 const totalItems = items.length;

 const stepAngle = useMemo(() => {
 if (!totalItems) return 0;
 return 360 / totalItems;
 }, [totalItems]);

 const panelAngle = useMemo(() => {
 return stepAngle + gap;
 }, [stepAngle, gap]);

 const normalizeIndex = (index) => {
 if (!totalItems) return 0;
 return ((index % totalItems) + totalItems) % totalItems;
 };

 const stopMomentum = () => {
 if (momentumFrameRef.current) {
 cancelAnimationFrame(momentumFrameRef.current);
 momentumFrameRef.current = null;
 }
 };

 const stopAutoplay = () => {
 if (autoplayRef.current) {
 clearInterval(autoplayRef.current);
 autoplayRef.current = null;
 }
 };

 const getRotationForStep = (step) => {
 return 180 + step * stepAngle;
 };

 const setActiveFromStep = (step) => {
 setActiveIndex(normalizeIndex(step));
 };

 const rotateToStep = (step, animate = true) => {
 if (!ringRef.current || !totalItems) return;

 currentStepRef.current = step;
 setActiveFromStep(step);

 const targetRotation = getRotationForStep(step);

 if (animate) {
 gsap.to(ringRef.current, {
 rotationY: targetRotation,
 duration: 0.7,
 ease:"power3.out",
 });
 } else {
 gsap.set(ringRef.current, {
 rotationY: targetRotation,
 });
 }
 };

 const updateStepFromRotation = () => {
 if (!ringRef.current || !stepAngle) return;

 const currentRotation = Number(gsap.getProperty(ringRef.current,"rotationY"));
 const rawStep = Math.round((currentRotation - 180) / stepAngle);

 currentStepRef.current = rawStep;
 setActiveFromStep(rawStep);
 };

 const goToNext = (fromAutoplay = false) => {
 stopMomentum();

 if (!fromAutoplay) {
 stopAutoplay();
 }

 rotateToStep(currentStepRef.current + 1);
 };

 const goToPrev = () => {
 stopMomentum();
 stopAutoplay();
 rotateToStep(currentStepRef.current - 1);
 };

 const goToSlide = (targetIndex) => {
 stopMomentum();
 stopAutoplay();

 const currentStep = currentStepRef.current;
 const currentVisualIndex = normalizeIndex(currentStep);

 const forwardDistance =
 (targetIndex - currentVisualIndex + totalItems) % totalItems;
 const backwardDistance =
 (currentVisualIndex - targetIndex + totalItems) % totalItems;

 const nextStep =
 forwardDistance <= backwardDistance
 ? currentStep + forwardDistance
 : currentStep - backwardDistance;

 rotateToStep(nextStep);
 };

 const startAutoplay = () => {
 if (!autoPlay || totalItems <= 1) return;

 stopAutoplay();

 autoplayRef.current = setInterval(() => {
 if (pauseOnHover && isHoveredRef.current) return;
 goToNext(true);
 }, autoPlayInterval);
 };

 useLayoutEffect(() => {
 if (!totalItems) return;

 const ring = ringRef.current;
 const dragger = draggerRef.current;
 const panels = itemRefs.current.filter(Boolean);

 if (!ring || !dragger || !panels.length) return;

 const updateRingRotation = (deltaX) => {
 const rotationDelta = deltaX * dragSensitivity;

 gsap.set(ring, {
 rotationY: `-=${rotationDelta}`,
 });

 updateStepFromRotation();
 };

 const runMomentum = () => {
 stopMomentum();

 const animate = () => {
 velocityRef.current *= friction;

 if (Math.abs(velocityRef.current) < 0.02) {
 velocityRef.current = 0;

 if (snap && stepAngle > 0) {
 updateStepFromRotation();
 rotateToStep(currentStepRef.current);
 }

 return;
 }

 gsap.set(ring, {
 rotationY: `-=${velocityRef.current}`,
 });

 updateStepFromRotation();
 momentumFrameRef.current = requestAnimationFrame(animate);
 };

 momentumFrameRef.current = requestAnimationFrame(animate);
 };

 const ctx = gsap.context(() => {
 gsap.set(dragger, { opacity: 0 });

 currentStepRef.current = 0;

 gsap.set(ring, {
 rotationY: getRotationForStep(0),
 transformStyle:"preserve-3d",
 });

 gsap.set(panels, {
 rotateY: (i) => i * -panelAngle,
 transformOrigin: `50% 50% ${radius}px`,
 z: -radius,
 width: itemWidth,
 height: itemHeight,
 left:"50%",
 top:"50%",
 xPercent: -50,
 yPercent: -50,
 backfaceVisibility:"hidden",
 transformStyle:"preserve-3d",
 });

 gsap.from(panels, {
 duration: 1.2,
 y: 120,
 opacity: 0,
 stagger: 0.08,
 ease:"expo.out",
 });

 Draggable.create(dragger, {
 type:"x,y",
 trigger: dragger,
 onPress: function (e) {
 stopMomentum();
 stopAutoplay();

 const clientX = e.touches ? e.touches[0].clientX : e.clientX;
 lastXRef.current = clientX;
 velocityRef.current = 0;
 },
 onDrag: function (e) {
 const clientX = e.touches ? e.touches[0].clientX : e.clientX;
 const deltaX = clientX - lastXRef.current;

 updateRingRotation(deltaX);
 velocityRef.current = deltaX * momentum;
 lastXRef.current = clientX;
 },
 onRelease: function () {
 gsap.set(dragger, { x: 0, y: 0 });
 runMomentum();

 if (!(pauseOnHover && isHoveredRef.current) && autoPlay) {
 startAutoplay();
 }
 },
 });
 }, containerRef);

 return () => {
 stopMomentum();
 ctx.revert();
 };
 }, [
 totalItems,
 itemWidth,
 itemHeight,
 radius,
 panelAngle,
 dragSensitivity,
 momentum,
 friction,
 snap,
 stepAngle,
 autoPlay,
 pauseOnHover,
 autoPlayInterval,
 ]);

 useEffect(() => {
 if (autoPlay && totalItems > 1 && !(pauseOnHover && isHoveredRef.current)) {
 startAutoplay();
 } else {
 stopAutoplay();
 }

 return () => {
 stopAutoplay();
 };
 }, [autoPlay, autoPlayInterval, totalItems, pauseOnHover]);

 return (
 <div
 className={`ring-gallery ${className}`}
 ref={containerRef}
 onMouseEnter={() => {
 isHoveredRef.current = true;
 if (pauseOnHover) stopAutoplay();
 }}
 onMouseLeave={() => {
 isHoveredRef.current = false;
 if (pauseOnHover && autoPlay) startAutoplay();
 }}
 >
 <div className="ring-gallery__container">
 <div className="ring-gallery__ring" ref={ringRef}>
 {items.map((item, i) => {
 const isImage = typeof item ==="string";

 return (
