const REPULSION_RADIUS = 1.5
const REPULSION_STRENGTH = 0.012

function Connector({
  position,
  children,
  vec = new THREE.Vector3(),
  repulsion = new THREE.Vector3(),
  r = THREE.MathUtils.randFloatSpread,
  accent,
  connectorRefs,
  index,
  ...props
}) {
  const api = useRef()
  const pos = useMemo(() => position || [r(10), r(10), r(10)], [position, r])

  useMemo(() => {
    connectorRefs.current[index] = api
  }, [index, connectorRefs])

  useFrame((state, delta) => {
    delta = Math.min(0.1, delta)
    if (!api.current) return

    const myPos = api.current.translation()

    api.current.applyImpulse(
      vec.copy(myPos).negate().multiplyScalar(0.01)
    )

    for (let i = 0; i < connectorRefs.current.length; i++) {
      if (i === index) continue
      const other = connectorRefs.current[i]?.current
      if (!other) continue

      const otherPos = other.translation()
      repulsion.set(
        myPos.x - otherPos.x,
        myPos.y - otherPos.y,
        myPos.z - otherPos.z
      )
      const dist = repulsion.length()

      if (dist < REPULSION_RADIUS && dist > 0.001) {
        const force = (REPULSION_RADIUS - dist) / REPULSION_RADIUS
        repulsion.normalize().multiplyScalar(force * REPULSION_STRENGTH)
        api.current.applyImpulse(repulsion)
      }
    }
  })

  return (
    <RigidBody
      linearDamping={4}
      angularDamping={1}
      friction={0.1}
      position={pos}
      ref={api}
      colliders={false}
    >
      <CuboidCollider
        args={[
          0.25 * COLLIDER_SCALE,
          1.2 * COLLIDER_SCALE,
          0.25 * COLLIDER_SCALE,
        ]}
        position={[-1.2 * COLLIDER_SCALE, 0, 0]}
      />
      <CuboidCollider
        args={[
          0.25 * COLLIDER_SCALE,
          1.2 * COLLIDER_SCALE,
          0.25 * COLLIDER_SCALE,
        ]}
        position={[0.8 * COLLIDER_SCALE, 0, 0]}
      />
      <CuboidCollider
        args={[
          1.1 * COLLIDER_SCALE,
          0.2 * COLLIDER_SCALE,
          0.25 * COLLIDER_SCALE,
        ]}
        position={[0, 0, 0]}
      />
      {children ? children : <Model {...props} />}
      {accent && (
        <pointLight intensity={4} distance={1.25} color={props.color} />
      )}
    </RigidBody>
  )
}

function Pointer({ vec = new THREE.Vector3() }) {
  const ref = useRef()

  useFrame(({ mouse, viewport }) => {
    const x = (mouse.x * viewport.width) / 2
    const y = (mouse.y * viewport.height) / 2

    // Constrain pointer to canvas bounds
    const maxX = viewport.width / 2
    const maxY = viewport.height / 2

    const constrainedX = Math.max(-maxX, Math.min(maxX, x))
    const constrainedY = Math.max(-maxY, Math.min(maxY, y))

    ref.current?.setNextKinematicTranslation(
      vec.set(constrainedX, constrainedY, 0)
    )
  })

  return (
    <RigidBody
      position={[0, 0, 0]}
      type="kinematicPosition"
      colliders={false}
      ref={ref}
    >
      <BallCollider args={[POINTER_RADIUS]} />
    </RigidBody>
  )
}

function Model({ children, color = 'white', roughness = 0 }) {
  const ref = useRef()
  const { nodes } = useGLTF('/models/hyperiux-logo.glb')
  const { nodes : nodes2 , materials : materials2 } = useGLTF('/models/c-transformed.glb')
  const geometry = nodes.FINAL?.geometry
  console.log(materials2)

  useFrame((state, delta) => {
    if (ref.current?.material?.color) {
      easing.dampC(ref.current.material.color, color, 0.2, delta)
    }
  })

  if (!geometry) return null

  return (
    <mesh
      ref={ref}
      castShadow
      receiveShadow
      scale={[MODEL_SCALE, MODEL_SCALE, MODEL_SCALE * 2.3]}
      geometry={geometry}
    >
      <meshPhysicalMaterial
        metalness={.4}
        roughness={0.2}
        clearcoat={1}
        clearcoatRoughness={0.2}
        material={materials2.base}
        reflectivity={1}
        color={color}
      />

      {children}
    </mesh>
  )
}

