    loader.setCrossOrigin("anonymous");
    let loaded = 0;

    imagesArr.forEach((src, idx) => {
      loader.load(
        src,
        (tex) => {
          texturesRef.current[idx] = tex;
          if (++loaded === imagesArr.length) setImagesLoaded(true);
        },
        undefined,
        (err) => {
          console.error("Failed to load texture:", err);
          texturesRef.current[idx] = null;
          if (++loaded === imagesArr.length) setImagesLoaded(true);
