"use client";
import { useRef, useCallback, useEffect, useState } from "react";
import { gsap } from "gsap";
import { Draggable } from "gsap/Draggable";
import { InertiaPlugin } from "gsap/InertiaPlugin";

gsap.registerPlugin(Draggable, InertiaPlugin);

export default function MaskedContainer({
  size,
  initialPosition,
  className,
  video,
  canvasSize,
  onPositionUpdate,
  onHoverChange,
}) {
  const maskRef = useRef(null);
  const canvasRef = useRef(null);
  const animationFrameRef = useRef(null);
  const [position, setPosition] = useState(initialPosition);

  // Canvas drawing function for individual mask
  const drawMaskedVideo = useCallback(() => {
    const canvas = canvasRef.current;
    const maskElement = maskRef.current;

    if (!canvas || !video || !maskElement) return;

    const ctx = canvas.getContext("2d");
    const rect = maskElement.getBoundingClientRect();

    // Set canvas size to match mask
    canvas.width = rect.width;
    canvas.height = rect.height;

    // Clear canvas with black background
    ctx.fillStyle = "black";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Calculate video position relative to the mask position
    const maskX = rect.left;
    const maskY = rect.top;

    // Draw the portion of the video that should be visible through this mask
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, canvas.width, canvas.height);
    ctx.clip();

    // Draw video with offset to show the correct portion
    ctx.drawImage(video, -maskX, -maskY, canvasSize.width, canvasSize.height);
    ctx.restore();
  }, [video, canvasSize]);

  // Animation loop for individual mask
  const animate = useCallback(() => {
    drawMaskedVideo();
    animationFrameRef.current = requestAnimationFrame(animate);
  }, [drawMaskedVideo]);

  // Start animation when video is available
  useEffect(() => {
    if (video) {
      animate();
    }

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [video, animate]);

  // GSAP Draggable functionality
  useEffect(() => {
    if (maskRef.current) {
      const draggable = Draggable.create(maskRef.current, {
        type: "x,y",
        inertia: true,
        bounds: "body",
        edgeResistance: 0.3,
        throwProps: {
          resistance: 500,
          minDuration: 2,
          maxDuration: 3
        },
        onDrag: function () {
          setPosition({ x: this.x, y: this.y });
          onPositionUpdate(size, { x: this.x, y: this.y });
        },
        onThrowUpdate: function () {
          setPosition({ x: this.x, y: this.y });
          onPositionUpdate(size, { x: this.x, y: this.y });
        }
      })[0];

      return () => {
        if (draggable) {
          draggable.kill();
        }
      };
    }
  }, [size, onPositionUpdate ]);

  return (
    <div
      ref={maskRef}
      className={`${className} cursor-grab active:cursor-grabbing z-10 overflow-hidden border border-zinc-500`}
      onMouseEnter={() => onHoverChange?.(true)}
      onMouseLeave={() => onHoverChange?.(false)}
    >
      <div className=" absolute flex gap-2 text-white/70 h-fit w-fit text-[.6vw] px-[.5vw] pt-[.3vw] py-[.1vw]">
        <p>X:{position.x.toFixed(2)}</p>
        <p>Y:{position.y.toFixed(2)}</p>
      </div>
      {/* Canvas for rendering masked video */}
      <canvas ref={canvasRef} className="w-full h-full" />
    </div>
  );
}

'use client'

import React, { useMemo, useRef } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { useTexture } from '@react-three/drei'
import * as THREE from 'three/webgpu'
import { texture, uv, uniform, sub, length, mul, add, oneMinus, vec2 } from 'three/tsl'

const damp = (current, target, lambda, delta) =>
  current + (target - current) * (1 - Math.exp(-lambda * delta))

function ImageNodeMaterial({ src, isMobile }) {
  const map = useTexture(src)
  const { size, camera } = useThree()

  const height =
    2 * Math.tan((camera.fov * Math.PI) / 180 / 2) * camera.position.z

  const width = height * (size.width / size.height)

  const mouse = useRef(new THREE.Vector2(0.5, 0.5))
  const target = useRef(new THREE.Vector2(0.5, 0.5))
  const strength = useRef(0)
  const strengthTarget = useRef(0)

  const material = useMemo(() => {
    map.colorSpace = THREE.SRGBColorSpace

    const mat = new THREE.MeshBasicNodeMaterial()

    const mouseU = uniform(mouse.current)
    const strengthU = uniform(0)

    const baseUV = uv()
    const diff = sub(baseUV, mouseU)
    const dist = length(diff)

    const falloff = oneMinus(dist).pow(2)

    const displacement = mul(diff, falloff).mul(strengthU.negate())

    const distortedUV = add(baseUV, displacement)

    mat.colorNode = texture(map, distortedUV)

    mat.userData.mouseU = mouseU
    mat.userData.strengthU = strengthU

    return mat
  }, [map])

  useFrame((_, delta) => {
    if (!isMobile) {
      mouse.current.x = damp(mouse.current.x, target.current.x, 12, delta)
      mouse.current.y = damp(mouse.current.y, target.current.y, 12, delta)

      strength.current = damp(
        strength.current,
        strengthTarget.current,
        8,
        delta
      )
    }

    material.userData.strengthU.value = isMobile ? 0 : strength.current
  })

  return (
    <mesh
      material={material}
      onPointerMove={
        isMobile
          ? undefined
          : (e) => {
              if (!e.uv) return
              target.current.copy(e.uv)
              strengthTarget.current = 1
            }
      }
      onPointerLeave={
        isMobile
          ? undefined
          : () => {
              target.current.set(0.5, 0.5)
              strengthTarget.current = 0
            }
      }
    >
      <planeGeometry args={[width, height]} />
    </mesh>
  )
}

export default function FishEyeImage({ src }) {
  const isMobile =
    typeof window !== 'undefined' &&
    window.matchMedia('(pointer: coarse)').matches

  return (
    <Canvas
      dpr={[1, 2]}
      camera={{ position: [0, 0, 5], fov: 45 }}
      className="h-full w-full"
      style={{
        pointerEvents: isMobile ? 'none' : 'auto',
        touchAction: isMobile ? 'none' : 'auto',
      }}
      gl={({ canvas }) => {
        const renderer = new THREE.WebGPURenderer({
          canvas,
          antialias: true,
        })

        renderer.outputColorSpace = THREE.SRGBColorSpace
        renderer.toneMapping = THREE.NoToneMapping
        renderer.init()

        return renderer
      }}
    >
      <ImageNodeMaterial src={src} isMobile={isMobile} />
    </Canvas>
  )
}

