"use client";

import React, { Suspense, useEffect, useRef, useState } from "react";
import { Canvas } from "@react-three/fiber";
import { Environment, OrbitControls } from "@react-three/drei";
import { CubeParticlesModel } from "./CubeParticlesModel";
import { CameraShakeOnHold } from "./CameraShakeOnHold";
import { HoldCursorIndicator } from "./HoldCursorIndicator";

const PHASE_IDLE = "idle";
const PHASE_HOLDING = "holding";
const PHASE_EXPLOADING = "exploding";
const PHASE_REFORMING = "reforming";

const DARK_TEXTURE_PATH = "/assets/models/new-logo-texture.png";
const LIGHT_TEXTURE_PATH = "/assets/models/hyperiux-logo-texture.png";
const HOLD_TRIGGER_DURATION = 3;

const HyperiuxLogo = () => {
  const [actionPhase, setActionPhase] = useState(PHASE_IDLE);
  const [burstKey, setBurstKey] = useState(0);
  const [isLightMode, setIsLightMode] = useState(false);

  const actionPhaseRef = useRef(PHASE_IDLE);
  const lockRef = useRef(false);
  const activePointerIdRef = useRef(null);
  const timersRef = useRef([]);
  const removeWindowReleaseRef = useRef(null);
  const holdStartTimeRef = useRef(0);
  const autoExplosionTimeoutRef = useRef(null);

  const explosionDuration = 3;
  const explodedHoldDuration = 1;
  const reformDuration = 3.5;
  const reformSettleBuffer = 0.12;

  useEffect(() => {
    actionPhaseRef.current = actionPhase;
  }, [actionPhase]);

  const clearTimers = () => {
    timersRef.current.forEach(clearTimeout);
    timersRef.current = [];
  };

  const clearAutoExplosionTimeout = () => {
    if (autoExplosionTimeoutRef.current) {
      clearTimeout(autoExplosionTimeoutRef.current);
      autoExplosionTimeoutRef.current = null;
    }
  };

  const clearWindowRelease = () => {
    if (removeWindowReleaseRef.current) {
      removeWindowReleaseRef.current();
      removeWindowReleaseRef.current = null;
    }
  };

  const resetCycle = () => {
    clearTimers();
    clearAutoExplosionTimeout();
    clearWindowRelease();

    lockRef.current = false;
    activePointerIdRef.current = null;
    holdStartTimeRef.current = 0;

    actionPhaseRef.current = PHASE_IDLE;
    setActionPhase(PHASE_IDLE);
  };

  const startExplosionSequence = () => {
    if (actionPhaseRef.current !== PHASE_HOLDING) return;

    clearWindowRelease();
    clearAutoExplosionTimeout();

    setBurstKey((v) => v + 1);
    actionPhaseRef.current = PHASE_EXPLOADING;
    setActionPhase(PHASE_EXPLOADING);

    timersRef.current.push(
      setTimeout(() => {
        actionPhaseRef.current = PHASE_REFORMING;
        setActionPhase(PHASE_REFORMING);
      }, (explosionDuration + explodedHoldDuration) * 1000)
    );

    timersRef.current.push(
      setTimeout(() => {
        resetCycle();
      }, (explosionDuration +
        explodedHoldDuration +
        reformDuration +
        reformSettleBuffer) * 1000)
    );
  };

  const startHold = (e) => {
    if (lockRef.current) return;
    if (actionPhaseRef.current !== PHASE_IDLE) return;

    clearTimers();
    clearAutoExplosionTimeout();
    clearWindowRelease();

    lockRef.current = true;
    activePointerIdRef.current = e.pointerId ?? null;
    holdStartTimeRef.current = performance.now();

    actionPhaseRef.current = PHASE_HOLDING;
    setActionPhase(PHASE_HOLDING);

    autoExplosionTimeoutRef.current = setTimeout(() => {
      startExplosionSequence();
    }, HOLD_TRIGGER_DURATION * 1000);

    const handleWindowPointerUp = (ev) => {
      if (actionPhaseRef.current !== PHASE_HOLDING) return;

      if (
        activePointerIdRef.current !== null &&
        ev.pointerId !== undefined &&
        ev.pointerId !== activePointerIdRef.current
      ) {
        return;
      }

      // Before 3 seconds: cancel and reset
      resetCycle();
    };

    const handleWindowPointerCancel = (ev) => {
      if (actionPhaseRef.current !== PHASE_HOLDING) return;

      if (
        activePointerIdRef.current !== null &&
        ev.pointerId !== undefined &&
        ev.pointerId !== activePointerIdRef.current
      ) {
        return;
      }

      resetCycle();
    };

    window.addEventListener("pointerup", handleWindowPointerUp, {
      passive: true,
    });
    window.addEventListener("pointercancel", handleWindowPointerCancel, {
      passive: true,
    });

    removeWindowReleaseRef.current = () => {
      window.removeEventListener("pointerup", handleWindowPointerUp);
      window.removeEventListener("pointercancel", handleWindowPointerCancel);
    };
  };

  useEffect(() => {
    return () => {
      clearTimers();
      clearAutoExplosionTimeout();
      clearWindowRelease();
    };
  }, []);

  const backgroundColor = isLightMode ? "#ffffff" : "#111111";
  const outlineColor = isLightMode ? "#000000" : "#ffffff";
  const faceColor = isLightMode ? "#ffffff" : "#1a1a1a";
  const texturePath = isLightMode ? LIGHT_TEXTURE_PATH : DARK_TEXTURE_PATH;

  return (
    <div
      className="w-full h-screen touch-none relative overflow-hidden"
      style={{ backgroundColor }}
      onPointerDown={startHold}
    >
      <HoldCursorIndicator
        isHolding={actionPhase === PHASE_HOLDING}
        actionPhase={actionPhase}
        holdStartTime={holdStartTimeRef.current}
      />

      <button
        type="button"
        onClick={() => setIsLightMode((prev) => !prev)}
        className="absolute top-6 right-6 z-20 px-4 py-2 rounded-full border text-sm font-medium backdrop-blur-md"
        style={{
          backgroundColor: isLightMode
            ? "rgba(255,255,255,0.9)"
            : "rgba(17,17,17,0.75)",
          color: isLightMode ? "#111111" : "#ffffff",
          borderColor: isLightMode ? "#111111" : "#ffffff",
        }}
      >
        {isLightMode ? "Dark mode" : "Light mode"}
      </button>

      <Canvas camera={{ position: [0, 0, 5], fov: 75 }}>
        <CameraShakeOnHold
          actionPhase={actionPhase}
          intensity={0.04}
          rotationIntensity={0.008}
          frequency={18}
          smooth={0.08}
        />

        <Suspense fallback={null}>
          <CubeParticlesModel
            modelPath="/assets/models/hyperiux-new-model.glb"
            texturePath={texturePath}
            position={[0, 0, 0]}
            rotation={[0, 0, 0]}
            scale={0.25}
            particleCount={835}
            cubeSize={0.36}
            cubeScaleVariation={0.01}
            centerCubeScaleMin={0.72}
            middleBridgeScaleMin={0.42}
            middleBridgeXInfluence={0.34}
            middleBridgeYInfluence={0.18}
            modelOpacity={0.0}
            outlineColor={outlineColor}
            faceColor={faceColor}
            frontVector={[0, 0, 1]}
            frontBiasPower={1.2}
            backFill={0.05}
            edgeBoost={0.35}
            edgeOutwardBias={0.12}
            edgeJitter={0.06}
            gridSnapFactor={1}
            surfaceJitter={0.1}
            interactionRadius={2.5}
            maxShrink={1.5}
            minScaleMultiplier={4.0}
            scaleLerp={0.14}
            parallaxPositionStrength={0.06}
            parallaxRotationStrength={0.2}
            floatingCubeCount={42}
            floatingYStartOffset={2}
            floatingYEndOffset={2}
            floatingZMin={-6}
            floatingZMax={2.5}
            floatingScaleMin={0.08}
            floatingScaleMax={0.28}
            floatingSpeedMin={0.08}
            floatingSpeedMax={0.2}
            floatingRotationSpeedMax={1.1}
            floatingXSpreadMultiplier={1.25}
            actionPhase={actionPhase}
            holdStartTime={holdStartTimeRef.current}
            holdTriggerDuration={HOLD_TRIGGER_DURATION}
            burstKey={burstKey}
            explosionDuration={explosionDuration}
            explodedHoldDuration={explodedHoldDuration}
            reformDuration={reformDuration}
            holdShakeAmount={0.12}
            holdShakeSpeed={30}
            explosionSpreadX={0}
            explosionSpreadY={0}
            explosionForwardMin={-30.5}
            explosionForwardMax={30.2}
            explosionBackwardMin={-50.2}
            explosionBackwardMax={44.8}
            explosionRotateMax={1.4}
          />
          <Environment preset="city" />
        </Suspense>

        <OrbitControls enabled={actionPhase === PHASE_IDLE} />
      </Canvas>
    </div>
  );
};

export default HyperiuxLogo;

"use client";

import { useEffect, useMemo, useRef, useState } from"react";
import InfiniteGrid from"./InfiniteGrid";
import styles from"./InfiniteGridGallery.module.css";

export default function InfiniteGridGallery() {
 const imagesRef = useRef(null);
 const gridRef = useRef(null);

 const expandThumbsRef = useRef(null);
 const expandThumbRefs = useRef([]);
 const thumbClickIndexRef = useRef(null);

 const thumbDragRef = useRef({
 active: false,
 pointerId: null,
 startX: 0,
 startScrollLeft: 0,
 moved: false,
 });

 const [expanded, setExpanded] = useState(null);
 const [isClosing, setIsClosing] = useState(false);
 const [isOpening, setIsOpening] = useState(false);
 const [displayIndex, setDisplayIndex] = useState(null);
 const [slide, setSlide] = useState(null);
 const [isThumbDragging, setIsThumbDragging] = useState(false);

 const closeTimerRef = useRef(null);
 const slideTimerRef = useRef(null);

 const slideDurationMs = 600;
 const openCloseDurationMs = 750;
 const isAnimating = isOpening || isClosing || Boolean(slide);

 const overlayLayout = useMemo(() => ({ thumbsH: 156 }), []);

 const unsplashPool = useMemo(
 () => [
 {
 src:"/assets/gradient/image1.png",
 title:"Velora Drift",
 },
 {
 src:"/assets/gradient/image12.png",
 title:"Zentha Bloom",
 },
 {
 src:"/assets/gradient/image3.png",
 title:"Auralis Fade",
 },
 {
 src:"/assets/gradient/image14.png",
 title:"Nyxara Flow",
 },
 {
 src:"/assets/gradient/image5.png",
 title:"Solune Mist",
 },
 {
 src:"/assets/gradient/image9.png",
 title:"Cryon Pulse",
 },
 {
 src:"/assets/gradient/image6.png",
 title:"Luneth Glow",
 },
 {
 src:"/assets/gradient/image7.png",
 title:"Virel Shift",
 },
 {
 src:"/assets/gradient/image10.png",
 title:"Orvyn Haze",
 },
 {
 src:"/assets/gradient/image8.png",
 title:"Draxen Veil",
 },
 {
 src:"/assets/gradient/image11.png",
 title:"Kaelis Tone",
 },
 {
 src:"/assets/gradient/image2.png",
 title:"Myra Flux",
 },
 {
 src:"/assets/gradient/image13.png",
 title:"Zypher Blend",
 },
 {
 src:"/assets/gradient/image4.png",
 title:"Elyon Sweep",
 },
 {
 src:"/assets/gradient/image15.png",
 title:"Thyra Wave",
 },
 ],
 []
);

 const sources = useMemo(
 () =>
 Array.from({ length: 120 }, (_, i) => {
 const pick = unsplashPool[i % unsplashPool.length];

 return {
 src: pick.src,
 caption: (() => {
 // Deterministic"random" name per index (stable across reloads).
 const adjectives = [
"Silent",
"Soft",
"Luminous",
"Velvet",
"Electric",
"Drifting",
"Infinite",
"Neon",
"Golden",
"Hidden",
"Crystal",
"Midnight",
"Warm",
"Icy",
"Dusty",
"Liquid",
"Misty",
"Aurora",
"Calm",
"Vivid",
 ];

 const nouns = [
"Horizon",
"Gradient",
"Bloom",
"Echo",
"Field",
"Wave",
"Ridge",
"Atlas",
"Canvas",
"Spectrum",
"Orbit",
"Shoreline",
"Valley",
"Glade",
"Tide",
"Mirage",
"Pulse",
"Drift",
"Skylight",
"Cascade",
 ];

 const a = adjectives[i % adjectives.length];
 const b = nouns[(i * 7) % nouns.length];
 return `${a} ${b}`;
 })(),
 };
 }),
 [unsplashPool]
 );

 const data = useMemo(() => {
 const cols = 3;
 const rows = 3;

 const itemW = 400;
 const itemH = 270;
 const gap = 40;
 const startX = 71;
 const startY = 58;

 return Array.from({ length: cols * rows }, (_, i) => {
 const col = i % cols;
 const row = Math.floor(i / cols);

 return {
 x: startX + col * (itemW + gap),
 y: startY + row * (itemH + gap),
 w: itemW,
 h: itemH,
 };
 });
}, []);

 useEffect(() => {
 const el = imagesRef.current;
 if (!el) return;

 const setRvw = () => {
 document.documentElement.style.setProperty(
"--rvw",
 `${document.documentElement.clientWidth / 100}px`
 );
 };

 setRvw();
 window.addEventListener("resize", setRvw);

 gridRef.current = new InfiniteGrid({
 el,
 sources,
 data,
 originalSize: { w: 1422, h: 1006 },
 onItemClick: ({ index, rect }) => {
 const vw = window.innerWidth;
 const vh = window.innerHeight;
 const thumbsH = overlayLayout.thumbsH;

 const maxH = Math.max(240, vh - thumbsH - 36);
 const targetW = Math.round(vw * 0.7);
 const targetH = Math.round(Math.min(vh * 0.7, maxH * 0.98));

 const targetLeft = Math.round((vw - targetW) / 2);
 const targetTop = Math.round((maxH - targetH) / 2);

 setIsClosing(false);
 setIsOpening(true);
 setExpanded({
 index,
 rect,
 vw,
 vh,
 target: {
 left: targetLeft,
 top: targetTop,
 width: targetW,
 height: targetH,
 },
 thumbsH,
 });
 setDisplayIndex(index);
 setSlide(null);
 },
 });

 return () => {
 window.removeEventListener("resize", setRvw);
 gridRef.current?.destroy?.();
 gridRef.current = null;
 };
 }, [data, sources, overlayLayout.thumbsH]);

 const active = expanded ? sources[expanded.index] : null;
 const display = displayIndex === null ? null : sources[displayIndex];

 const centerActiveThumb = (index, behavior ="smooth") => {
 const container = expandThumbsRef.current;
 const activeThumb = expandThumbRefs.current[index];

 if (!container || !activeThumb) return;

 const left =
 activeThumb.offsetLeft -
 container.clientWidth / 2 +
 activeThumb.clientWidth / 2;

 container.scrollTo({ left, behavior });
 };

 const navigateTo = (nextIndex) => {
 if (!expanded) return;
 if (isAnimating) return;

 if (nextIndex === expanded.index) {
 centerActiveThumb(nextIndex,"smooth");
 return;
 }

 const n = sources.length;
 const currentIndex = expanded.index;
 const forward = (nextIndex - currentIndex + n) % n;
 const backward = (currentIndex - nextIndex + n) % n;
 const dir = forward <= backward ? 1 : -1;

 window.clearTimeout(slideTimerRef.current);

 setSlide({ from: currentIndex, to: nextIndex, dir });
 setExpanded((s) => (!s ? s : { ...s, index: nextIndex }));

 slideTimerRef.current = window.setTimeout(() => {
 setDisplayIndex(nextIndex);
 setSlide(null);
 }, slideDurationMs);
 };

 const closeExpanded = () => {
 if (!expanded || isClosing) return;

 setIsClosing(true);
 setIsOpening(false);
 setSlide(null);

 window.clearTimeout(closeTimerRef.current);
 closeTimerRef.current = window.setTimeout(() => {
 setExpanded(null);
 setIsClosing(false);
 setDisplayIndex(null);
 }, openCloseDurationMs);
 };

 useEffect(() => {
 gridRef.current?.setEnabled?.(!expanded);
 }, [expanded]);

 useEffect(() => {
 if (!expanded) return;

 const id = requestAnimationFrame(() => setIsOpening(false));
 return () => cancelAnimationFrame(id);
 }, [expanded]);

 useEffect(() => {
 if (!expanded) return;

 requestAnimationFrame(() => {
 centerActiveThumb(expanded.index,"smooth");
 });
 }, [expanded?.index]);

 useEffect(() => {
 return () => {
 window.clearTimeout(slideTimerRef.current);
 window.clearTimeout(closeTimerRef.current);
 };
 }, []);

 useEffect(() => {
 if (!expanded) return;

 const onKeyDown = (e) => {
 if (e.key ==="Escape") closeExpanded();

 if (e.key ==="ArrowLeft") {
 navigateTo((expanded.index - 1 + sources.length) % sources.length);
 }

 if (e.key ==="ArrowRight") {
 navigateTo((expanded.index + 1) % sources.length);
 }
 };

 window.addEventListener("keydown", onKeyDown);
 return () => window.removeEventListener("keydown", onKeyDown);
 }, [expanded, sources.length]);

 const onThumbPointerDown = (e) => {
 const container = expandThumbsRef.current;
 if (!container) return;

 const button = e.target.closest("[data-thumb-index]");

 thumbClickIndexRef.current = button
 ? Number(button.getAttribute("data-thumb-index"))
 : null;

 thumbDragRef.current.active = true;
 thumbDragRef.current.pointerId = e.pointerId;
 thumbDragRef.current.startX = e.clientX;
 thumbDragRef.current.startScrollLeft = container.scrollLeft;
 thumbDragRef.current.moved = false;

 setIsThumbDragging(true);
 container.setPointerCapture?.(e.pointerId);
 };

 const onThumbPointerMove = (e) => {
 if (!thumbDragRef.current.active) return;
 if (thumbDragRef.current.pointerId !== e.pointerId) return;

 const container = expandThumbsRef.current;
 if (!container) return;

 const dx = e.clientX - thumbDragRef.current.startX;

 if (!thumbDragRef.current.moved && Math.abs(dx) > 3) {
 thumbDragRef.current.moved = true;
 }

 container.scrollLeft = thumbDragRef.current.startScrollLeft - dx;
 };

 const endThumbDrag = (e) => {
 if (!thumbDragRef.current.active) return;
 if (thumbDragRef.current.pointerId !== e.pointerId) return;

 const container = expandThumbsRef.current;
 container?.releasePointerCapture?.(e.pointerId);

 const clickedIndex = thumbClickIndexRef.current;
 const wasDragged = thumbDragRef.current.moved;

 thumbDragRef.current.active = false;
 thumbDragRef.current.pointerId = null;
 thumbClickIndexRef.current = null;

 setIsThumbDragging(false);

 if (!wasDragged && Number.isInteger(clickedIndex)) {
 navigateTo(clickedIndex);
 }

 window.setTimeout(() => {
 thumbDragRef.current.moved = false;
 }, 0);
 };

 const onThumbWheel = (e) => {
 const container = expandThumbsRef.current;
 if (!container) return;

 e.preventDefault();
 container.scrollLeft += e.deltaX || e.deltaY;
 };

 return (
 <section className={styles.root}>
 <div ref={imagesRef} className={styles.images} />

 {active && expanded && display ? (
 <div
