'use client'

import React, { useEffect, useMemo, useRef, useState } from'react'
import { Canvas, createPortal, useFrame, useThree } from'@react-three/fiber'
import { Text, useFBO } from'@react-three/drei'
import * as THREE from'three'
import gsap from'gsap'

// ---- CONFIGURATION ----
const TUNNEL_CONFIG = {
 ringCount: 5,
 countPerRing: 10,
 ringRadius: 2,
 ringStartScale: 0.01,
 ringEndScale: 8,
 ringRotateSpeed: 1.2,
 ringFadeInPhase: 0.1,
 ringFullVisiblePhase: 0.7,
 ringFadeOutPhase: 0.9,
 ringFontSize: 0.5,
 ringLetterSpacing: -0.05,
 textColor:'#ffffff',
 crossfadeDuration: 2,
 canvasFadeDuration: 500,
 tunnelFadeOutDelay: 5,
 loaderTickInterval: 40,
 loaderStartDelay: 1200,
 backgroundColor:'#000000'
}

function TunnelRing({ index, loaderValue, tunnelPhase }) {
 const groupRef = useRef()
 const ringContentRef = useRef()
 const direction = index % 2 === 0 ? 1 : -1

 const textMaterial = useMemo(
 () =>
 new THREE.MeshBasicMaterial({
 color: new THREE.Color(TUNNEL_CONFIG.textColor),
 transparent: true,
 opacity: 0,
 depthWrite: false,
 }),
 []
 )

 useEffect(() => {
 return () => textMaterial.dispose()
 }, [textMaterial])

 useFrame((state, delta) => {
 if (!groupRef.current || !ringContentRef.current) return

 const time = state.clock.getElapsedTime()
 const speed = 0.25

 // Instead of adding index mapped offset, subtract it to delay spawn.
 // This makes rings wait their turn to start from the center.
 const rawPhase = time * speed - index / TUNNEL_CONFIG.ringCount

 if (rawPhase < 0) {
 groupRef.current.scale.set(0.001, 0.001, 0.001)
 textMaterial.opacity = 0
 } else {
 const phase = rawPhase % 1

 // Scale calculation
 const scale =
 Math.pow(phase, 3) * TUNNEL_CONFIG.ringEndScale +
 TUNNEL_CONFIG.ringStartScale

 groupRef.current.scale.set(scale, scale, scale)

 // Opacity calculation by phase
 let opacity = 0
 if (phase < TUNNEL_CONFIG.ringFadeInPhase)
 opacity = phase / TUNNEL_CONFIG.ringFadeInPhase
 else if (phase <= TUNNEL_CONFIG.ringFullVisiblePhase)
 opacity = 1
 else if (phase <= TUNNEL_CONFIG.ringFadeOutPhase)
 opacity = 1 - (phase - TUNNEL_CONFIG.ringFullVisiblePhase) / (TUNNEL_CONFIG.ringFadeOutPhase - TUNNEL_CONFIG.ringFullVisiblePhase)
 else opacity = 0

 // Fade out rings as tunnelPhase progresses
 textMaterial.opacity = opacity * (1 - tunnelPhase)
 }

 ringContentRef.current.rotation.z += delta * TUNNEL_CONFIG.ringRotateSpeed * direction
 })

 return (
 <group ref={groupRef} position={[0, 0, -index * 0.01]}>
 <group ref={ringContentRef}>
 {Array.from({ length: TUNNEL_CONFIG.countPerRing }).map((_, i) => {
 const angle = (i / TUNNEL_CONFIG.countPerRing) * Math.PI * 2
 const x = Math.cos(angle) * TUNNEL_CONFIG.ringRadius
 const y = Math.sin(angle) * TUNNEL_CONFIG.ringRadius

 return (
 <Text
 key={i}
 position={[x, y, 0]}
 rotation={[0, 0, angle - Math.PI / 2]}
 fontSize={TUNNEL_CONFIG.ringFontSize}
 anchorX="center"
 anchorY="middle"
 letterSpacing={TUNNEL_CONFIG.ringLetterSpacing}
 material={textMaterial}
 >
 {loaderValue.toString().padStart(2,'0')}
 </Text>
 )
 })}
 </group>
 </group>
 )
}

function TunnelScene({ loaderValue, tunnelPhase }) {
 return (
 <>
 <color attach="background" args={[TUNNEL_CONFIG.backgroundColor]} />
 {Array.from({ length: TUNNEL_CONFIG.ringCount }).map((_, i) => (
 <TunnelRing key={i} index={i} loaderValue={loaderValue} tunnelPhase={tunnelPhase} />
 ))}
 </>
 )
}

function WholeSceneEffect({ children, active, tunnelPhase }) {
 const { gl, camera, size, viewport } = useThree()
 const portalScene = useMemo(() => new THREE.Scene(), [])
 const fbo = useFBO(size.width, size.height, { samples: 0, depth: false })

 // Pass tunnelPhase as a uniform for smooth shader transition
 const material = useMemo(() => {
 return new THREE.ShaderMaterial({
 depthTest: false,
 depthWrite: false,
 transparent: true,
 uniforms: {
 tDiffuse: { value: fbo.texture },
 uTime: { value: 0 },
 uStrength: { value: 10.5 },
 uResolution: { value: new THREE.Vector2(size.width, size.height) },
 uTunnelPhase: { value: 0 },
 },
 vertexShader: /* glsl */ `
 varying vec2 vUv;
 varying float vDeform;
 uniform float uTime;
 uniform float uStrength;
 uniform float uTunnelPhase;
 void main() {
 vUv = uv;
 vec3 pos = position;

 float isLeft = step(0.0, -pos.x);
 float deform = isLeft * (1.0 - (pos.x + 0.5) * 2.0);

 deform *= sin(uTime * 2.4 + pos.y * 7.0 + pos.x * 5.2) * 0.23 * uStrength;
 pos.x += deform * 0.28 * uTunnelPhase;
 pos.z += isLeft * sin(uTime * 1.7 + pos.x * 10.0) * 0.15 * uStrength * uTunnelPhase;

 vDeform = deform * uTunnelPhase;
 gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
 }
 `,
 fragmentShader: /* glsl */ `
 varying vec2 vUv;
 varying float vDeform;
 uniform sampler2D tDiffuse;
 uniform float uTunnelPhase;
 uniform float uTime;
 void main() {
 float aberrationAmount = vDeform * 0.04;
 vec2 offset = vec2(aberrationAmount, 0.0);

 vec4 cr = texture2D(tDiffuse, vUv + offset);
 vec4 cg = texture2D(tDiffuse, vUv);
 vec4 cb = texture2D(tDiffuse, vUv - offset);

 float alpha = max(cr.a, max(cg.a, cb.a));
 vec4 baseColor = vec4(cr.r, cg.g, cb.b, alpha);

 vec3 shiftColor = vec3(
 0.5 + 0.5 * sin(uTime * 3.0 + vUv.y * 10.0),
 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 10.0 + 2.0),
 0.5 + 0.5 * sin(uTime * 4.0 + vUv.y * 5.0 + 4.0)
 );

 float shiftIntensity = abs(vDeform) * .2;

 vec3 finalColor = mix(
 baseColor.rgb,
 baseColor.rgb * shiftColor * 2.5 + shiftColor * alpha * 0.3,
 clamp(shiftIntensity, 0.0, 1.0)
 );

 gl_FragColor = vec4(finalColor, alpha * uTunnelPhase);
 }
 `,
 })
 }, [fbo.texture, size.width, size.height])

 useEffect(() => {
 material.uniforms.uResolution.value.set(size.width, size.height)
 }, [material, size.width, size.height])

 useEffect(() => {
 return () => material.dispose()
 }, [material])

 useFrame((state, delta) => {
 // always render tunnel pass, then crossfade
 gl.setRenderTarget(fbo)
 gl.clear(true, true, true)
 gl.render(portalScene, camera)
 gl.setRenderTarget(null)

 material.uniforms.uTime.value = state.clock.getElapsedTime()
 material.uniforms.uTunnelPhase.value = tunnelPhase
 // Strength ramps with phase for extra pop; smooth easing
 material.uniforms.uStrength.value = THREE.MathUtils.lerp(
 5.5,
 1,
 tunnelPhase
 )
 })

 return (
 <>
 {createPortal(children, portalScene)}
 <group>{children}</group>
 <mesh
 scale={[viewport.width, viewport.height, 1]}
 position={[0, 0, 0]}
 renderOrder={10}
 >
 <planeGeometry args={[1, 1, 48, 48]} />
 <primitive object={material} attach="material" />
 </mesh>
 </>
 )
}

function NumericTunnelCanvas({ loaderValue, onComplete }) {
 const [effectActive, setEffectActive] = useState(false)
 // Remove useState for canvasOpacity, use a ref instead
 const canvasRef = useRef(null)
 const didScheduleRef = useRef(false)
 const [tunnelPhase, setTunnelPhase] = useState(0)

 useEffect(() => {
 let anim
 let fadeTimeout
 if (loaderValue >= 100 && !didScheduleRef.current) {
 didScheduleRef.current = true
 setEffectActive(true)
 let t = 0
 const duration = TUNNEL_CONFIG.crossfadeDuration
 const step = () => {
 t += 1 / 60
 setTunnelPhase(Math.min(t / duration, 1))
 if (t < duration) {
 anim = requestAnimationFrame(step)
 } else {
 fadeTimeout = setTimeout(() => {
 if (onComplete) {
 onComplete()
 return
 }
 // Animate opacity to 0 using GSAP; remove setCanvasOpacity, use ref
 if (canvasRef.current) {
 gsap.to(canvasRef.current, {
 opacity: 0,
 duration: TUNNEL_CONFIG.canvasFadeDuration / 1000,
 ease:"power3.inOut",
 })
 }
 }, TUNNEL_CONFIG.tunnelFadeOutDelay)
 }
 }
 requestAnimationFrame(step)
 }
 return () => {
 cancelAnimationFrame(anim)
 clearTimeout(fadeTimeout)
 }
 }, [loaderValue, onComplete])



 return (
 <div
 ref={canvasRef}
 className="h-full bg-black w-full"
 >
 <Canvas
 dpr={1}
 orthographic
 camera={{ zoom: 100, position: [0, 0, 10] }}
 gl={{ powerPreference:'high-performance' }}
 >
 <color attach="background" args={[TUNNEL_CONFIG.backgroundColor]} />
 <WholeSceneEffect active={effectActive} tunnelPhase={tunnelPhase}>
 <TunnelScene loaderValue={loaderValue} tunnelPhase={tunnelPhase} />
 </WholeSceneEffect>
 </Canvas>
 </div>
 )
}

export default function NumericTunnel({ onComplete }) {
 const [loaderValue, setLoaderValue] = useState(0)

 useEffect(() => {
 let interval;
 const timeout = setTimeout(() => {
 interval = setInterval(() => {
 setLoaderValue((prev) => (prev >= 100 ? 100 : prev + 1))
 }, TUNNEL_CONFIG.loaderTickInterval)
 }, TUNNEL_CONFIG.loaderStartDelay)

 return () => {
 clearTimeout(timeout)
 if (interval) clearInterval(interval)
 }
 }, [])

 return (
 <div className="h-screen w-full bg-white">
 <h2 className='absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-black text-[10vw] font-bold'>UI</h2>
 <NumericTunnelCanvas loaderValue={loaderValue} onComplete={onComplete} />
 </div>
 )
}

"use client";

import { useLayoutEffect, useRef, useState, useEffect } from "react";
import gsap from "gsap";

export default function TextMarquee({ items = [] }) {
  if (!items.length) return null;

  const trackRef = useRef(null);
  const contentRef = useRef(null);
  const containerRef = useRef(null);

  const [copyCount, setCopyCount] = useState(2);
  const [isMobile, setIsMobile] = useState(false);

  const metricsRef = useRef({
    currentY: 0,
    distance: 0,
    currentVelocity: 0.6,
    targetVelocity: 0.6,
    lastScrollDirection: 1,
  });

  const scrollTimeoutRef = useRef(null);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 640);

    check();
    window.addEventListener("resize", check);

    return () => window.removeEventListener("resize", check);
  }, []);

  useLayoutEffect(() => {
    const track = trackRef.current;
    const content = contentRef.current;
    const container = containerRef.current;

    if (!track || !content || !container) {
      return undefined;
    }

    const ctx = gsap.context(() => {
      const baseSpeed = 0.6;
      const maxBoost = 12;
      let lastScrollY = window.scrollY;

      const startAnimation = () => {
        const distance = content.offsetHeight;
        const containerHeight = container.offsetHeight;

        if (!distance || !containerHeight) return;

        const nextCopyCount = Math.max(
          2,
          Math.ceil(containerHeight / distance) + 2
        );

        setCopyCount((currentCount) =>
          currentCount === nextCopyCount ? currentCount : nextCopyCount
        );

        metricsRef.current.distance = distance;

        if (metricsRef.current.currentY <= -distance) {
          metricsRef.current.currentY += distance;
        } else if (metricsRef.current.currentY > 0) {
          metricsRef.current.currentY -= distance;
        }

        gsap.set(track, { y: metricsRef.current.currentY });
      };

      const tick = (_, deltaTime) => {
        const { distance } = metricsRef.current;

        if (!distance) return;

        const frameFactor = deltaTime / (1000 / 60);

        metricsRef.current.currentVelocity = gsap.utils.interpolate(
          metricsRef.current.currentVelocity,
          metricsRef.current.targetVelocity,
          0.14
        );

        metricsRef.current.currentY +=
          metricsRef.current.currentVelocity * frameFactor;

        if (metricsRef.current.currentY <= -distance) {
          metricsRef.current.currentY += distance;
        } else if (metricsRef.current.currentY >= 0) {
          metricsRef.current.currentY -= distance;
        }

        gsap.set(track, { y: metricsRef.current.currentY });
      };

      const applyScrollMotion = (delta) => {
        if (!delta) return;

        const direction = delta > 0 ? -1 : 1;

        const boost = Math.min(
          maxBoost,
          baseSpeed + Math.pow(Math.abs(delta), 1.2) * 0.08
        );

        metricsRef.current.lastScrollDirection = direction;
        metricsRef.current.targetVelocity = direction * boost;

        window.clearTimeout(scrollTimeoutRef.current);

        scrollTimeoutRef.current = window.setTimeout(() => {
          metricsRef.current.targetVelocity =
            metricsRef.current.lastScrollDirection * baseSpeed;
        }, 120);
      };

      const handleWheel = (event) => {
        applyScrollMotion(event.deltaY);
      };

      const handleScroll = () => {
        const nextScrollY = window.scrollY;
        const delta = nextScrollY - lastScrollY;

        lastScrollY = nextScrollY;

        applyScrollMotion(delta);
      };

      startAnimation();

      gsap.ticker.add(tick);

      const resizeObserver = new ResizeObserver(startAnimation);

      resizeObserver.observe(content);
      resizeObserver.observe(container);

      window.addEventListener("resize", startAnimation);
      window.addEventListener("wheel", handleWheel, {
        passive: true,
      });

      window.addEventListener("scroll", handleScroll, {
        passive: true,
      });

      return () => {
        resizeObserver.disconnect();

        window.removeEventListener("resize", startAnimation);
        window.removeEventListener("wheel", handleWheel);
        window.removeEventListener("scroll", handleScroll);

        window.clearTimeout(scrollTimeoutRef.current);

        gsap.ticker.remove(tick);
      };
    });

    return () => ctx.revert();
  }, []);

  const revealMask = isMobile
    ? "linear-gradient(to bottom, rgba(0,0,0,0.2) 0%, rgba(0,0,0,0.2) 49%, rgba(0,0,0,1) 49%, rgba(0,0,0,1) 52%, rgba(0,0,0,0.2) 52%, rgba(0,0,0,0.2) 100%)"
    : "linear-gradient(to bottom, rgba(0,0,0,0.2) 0%, rgba(0,0,0,0.2) 48%, rgba(0,0,0,1) 48%, rgba(0,0,0,1) 53%, rgba(0,0,0,0.3) 53%, rgba(0,0,0,0.3) 100%)";

  return (
    <div className="flex h-screen">
      <div className="w-[45%] flex max-sm:w-[30%] items-center justify-end pr-2">
        <p className="max-sm:text-xl text-4xl font-extralight leading-none whitespace-nowrap">
          Hyperiux
        </p>
      </div>

      <div
        ref={containerRef}
        className="relative w-[55%] max-sm:w-[70%] h-full overflow-hidden "
        style={{
          maskImage: revealMask,
          WebkitMaskImage: revealMask,
        }}
      >
        <div
          ref={trackRef}
          className="absolute left-0 top-0 flex flex-col max-sm:text-xl text-4xl font-extralight leading-none"
        >
          {Array.from({ length: copyCount }, (_, copyIndex) => (
            <div
              key={copyIndex}
              ref={copyIndex === 0 ? contentRef : null}
              className="flex flex-col"
              aria-hidden={copyIndex === 1}
            >
              {items.map((text, i) => (
                <div
  key={`${copyIndex}-${i}`}
  className="
    py-1
    pl-2
    whitespace-nowrap
    max-sm:whitespace-normal
    max-sm:wrap-break-word
    max-sm:pr-3
    max-sm:max-w-full
  "
>
                  {text}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useRef } from "react";
import { gsap, Expo } from "gsap";

import "./base.css";
import { useMouse } from "../hooks/useMouse";

const BASE_IMAGE_COUNT = 20;
const MOBILE_POINTER_QUERY = "(pointer: coarse)";
const OFFSCREEN_POSITION = -9999;
const IDLE_DISTANCE_THRESHOLD = 2;
const TRIGGER_DISTANCE_THRESHOLD = 100;
const INITIAL_Z_INDEX = 1;

export default function ImagesAnimation({
  enableRotation = true,
  idleSpawn = true,
  idleDelay = 300,
  cursorOffsetX = -12,
  cursorOffsetY = -12,
  popOutDuration = 1,
  fadeOutDuration = 0.7,
  imageMultiplier = 3,
  idlePopOutMultiplier = 1.8,
  idleFadeMultiplier = 1.5,
}) {
  // State and refs
  const imagesRef = useRef([]);
  const animationFrameRef = useRef(null);
  const idleTimerRef = useRef(null);
  const isMobileRef = useRef(
    typeof window !== "undefined" &&
      window.matchMedia(MOBILE_POINTER_QUERY).matches
  );
  const lastTriggerPositionRef = useRef({ x: 0, y: 0 });
  const lastIdleSpawnPositionRef = useRef({
    x: OFFSCREEN_POSITION,
    y: OFFSCREEN_POSITION,
  });
  const zIndexRef = useRef(INITIAL_Z_INDEX);
  const imageIndexRef = useRef(0);

  const { mouse, smoothMouse } = useMouse({
    smooth: true,
    lerpFactor: 0.1,
  });

  // Derived values
  const totalImages = BASE_IMAGE_COUNT * imageMultiplier;

  const getMouseDistance = () => {
    const currentMouse = mouse.current;
    const lastTriggerPosition = lastTriggerPositionRef.current;

    return Math.hypot(
      currentMouse.x - lastTriggerPosition.x,
      currentMouse.y - lastTriggerPosition.y
    );
  };

  const getIdleDistance = () => {
    const currentMouse = mouse.current;
    const lastIdleSpawnPosition = lastIdleSpawnPositionRef.current;

    return Math.hypot(
      currentMouse.x - lastIdleSpawnPosition.x,
      currentMouse.y - lastIdleSpawnPosition.y
    );
  };

  const getCenteredPosition = (width, height, useSmoothMouse = false) => {
    const mouseSource = useSmoothMouse ? smoothMouse.current : mouse.current;

    return {
      x: mouseSource.x - width / 2 + cursorOffsetX,
      y: mouseSource.y - height / 2 + cursorOffsetY,
    };
  };

  const showNextImage = ({
    lockToCursor = false,
    isIdle = false,
    overridePosition = null,
  } = {}) => {
    const image = imagesRef.current[imageIndexRef.current];

    if (!image) {
      return;
    }

    const width = image.offsetWidth;
    const height = image.offsetHeight;

    gsap.killTweensOf(image);

    const startRotation = enableRotation ? gsap.utils.random(-35, 35) : 0;
    const exitRotation = enableRotation ? gsap.utils.random(-15, 15) : 0;

    let startPosition;
    let endPosition;

    if (overridePosition) {
      startPosition = {
        x: overridePosition.x - width / 2 + cursorOffsetX,
        y: overridePosition.y - height / 2 + cursorOffsetY,
      };
      endPosition = startPosition;
    } else {
      startPosition = lockToCursor
        ? getCenteredPosition(width, height)
        : getCenteredPosition(width, height, true);
      endPosition = getCenteredPosition(width, height);
    }

    const finalPopOutDuration = isIdle
      ? popOutDuration * idlePopOutMultiplier
      : popOutDuration;
    const finalFadeOutDuration = isIdle
      ? fadeOutDuration * idleFadeMultiplier
      : fadeOutDuration;

    gsap
      .timeline()
      .set(image, {
        opacity: 1,
        scale: 0.2,
        rotateZ: startRotation,
        zIndex: zIndexRef.current,
        x: startPosition.x,
        y: startPosition.y,
      })
      .to(image, {
        ease: isIdle ? "power1.out" : Expo.easeOut,
        rotateZ: 0,
        opacity: 1,
        scale: 1,
        duration: finalPopOutDuration,
        x: endPosition.x,
        y: endPosition.y,
      })
      .to(image, {
        ease: "power4.inOut",
        opacity: 0,
        rotateZ: exitRotation,
        duration: finalFadeOutDuration,
        delay: -finalFadeOutDuration,
        scale: 0,
      });

    zIndexRef.current += 1;
    imageIndexRef.current =
      (imageIndexRef.current + 1) % imagesRef.current.length;
  };

  const scheduleIdleSpawn = () => {
    if (!idleSpawn) {
      return;
    }

    if (idleTimerRef.current) {
      clearTimeout(idleTimerRef.current);
    }

    idleTimerRef.current = setTimeout(() => {
      if (getIdleDistance() < IDLE_DISTANCE_THRESHOLD) {
        showNextImage({
          lockToCursor: true,
          isIdle: true,
        });
      }

      lastIdleSpawnPositionRef.current = { ...mouse.current };
      scheduleIdleSpawn();
    }, idleDelay);
  };

  const runAnimationLoop = () => {
    if (isMobileRef.current) {
      animationFrameRef.current = requestAnimationFrame(runAnimationLoop);
      return;
    }

    if (getMouseDistance() > TRIGGER_DISTANCE_THRESHOLD) {
      showNextImage();

      lastTriggerPositionRef.current = { ...mouse.current };
      lastIdleSpawnPositionRef.current = { ...mouse.current };

      if (idleSpawn) {
        scheduleIdleSpawn();
      }
    }

    const allImagesInactive = imagesRef.current.every(
      (image) => image && !gsap.isTweening(image) && image.style.opacity === "0"
    );

    if (allImagesInactive) {
      zIndexRef.current = INITIAL_Z_INDEX;
    }

    animationFrameRef.current = requestAnimationFrame(runAnimationLoop);
  };

  const onTap = (event) => {
    if (!isMobileRef.current) {
      return;
    }

    const touch = event.changedTouches?.[0] || event;
    const tapPosition = {
      x: touch.clientX,
      y: touch.clientY,
    };

    showNextImage({
      overridePosition: tapPosition,
    });
  };

  // Effects
  useEffect(() => {
    isMobileRef.current =
      typeof window !== "undefined" &&
      window.matchMedia(MOBILE_POINTER_QUERY).matches;

    animationFrameRef.current = requestAnimationFrame(runAnimationLoop);

    if (idleSpawn && !isMobileRef.current) {
      scheduleIdleSpawn();
    }

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }

      if (idleTimerRef.current) {
        clearTimeout(idleTimerRef.current);
      }
    };
  }, [idleDelay, idleSpawn]);

  // Return
  return (
    <div
      className="content"
      onClick={onTap}
      style={{
        position: "relative",
        width: "100%",
        height: "100vh",
        overflow: "hidden",
      }}
    >
      {Array.from({ length: totalImages }).map((_, index) => {
        const baseImageIndex = (index % BASE_IMAGE_COUNT) + 1;

        return (
          <img
            key={index}
            className="content__img"
            src={`/img/${baseImageIndex}.png`}
            alt={`Trail ${baseImageIndex}`}
            ref={(element) => {
              if (element) {
                imagesRef.current[index] = element;
              }
            }}
          />
        );
      })}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import gsap from "gsap";
import { ChevronDown, ChevronRight, ChevronUp } from "lucide-react";

const MENU_ITEMS = [
  {
    name: "Effects",
    href: "/effects",
    isDropdown: true,
    dropdown: [
      { title: "All Effects", img: "/img/dino2.png", href: "/effects" },
      { title: "Components", img: "/img/dino2.png", href: "/effects/components" },
      { title: "WebGL", img: "/img/dino2.png", href: "/effects/webgl" },
    ],
  },
  {
    name: "Tech",
    href: "/tech",
    isDropdown: true,
    dropdown: [
      { title: "React Effects", img: "/img/dino2.png", href: "/tech/react" },
      { title: "GSAP Effects", img: "/img/dino2.png", href: "/tech/gsap" },
      { title: "Three.js Effects", img: "/img/dino2.png", href: "/tech/threejs" },
    ],
  },
  {
    name: "Extras",
    href: "#",
    isDropdown: false,
    dropdown: null,
  },
  {
    name: "Docs",
    href: "/docs",
    isDropdown: true,
    dropdown: [
      { title: "Introduction", img: "/img/dino2.png", href: "/docs" },
      { title: "Installation", img: "/img/dino2.png", href: "/docs/installation" },
      { title: "CLI", img: "/img/dino2.png", href: "/docs/cli" },
    ],
  },
];

const DROPDOWN_ITEM_OFFSET_Y = -14;
const NAV_TEXT_DURATION = 0.35;
const CTA_DURATION = 0.4;
const DROPDOWN_POINTER_DELAY = 0.08;
const NAV_POINTER_DELAY = 0.06;
const DIMMED_TEXT_COLOR = "rgba(255,255,255,0.5)";
const ACTIVE_TEXT_COLOR = "rgba(255,255,255,1)";
const DEFAULT_CTA_BACKGROUND = "#fff";
const HOVER_CTA_BACKGROUND = "#000";
const IMAGE_TINT = "rgba(255, 0, 0, 0.9)";

export default function ElevateNavbarDesktop() {
  // State & refs
  const navWrapRef = useRef(null);
  const navLinksRef = useRef([]);
  const ctaRef = useRef(null);
  const dropdownRef = useRef(null);
  const dropdownItemsRef = useRef([]);
  const dropdownTextDataRef = useRef([]);
  const linkDataRef = useRef([]);
  const activeDropdownIndexRef = useRef(null);
  const isPointerInsideDropdownRef = useRef(false);
  const hideCallRef = useRef(null);
  const switchTweenRef = useRef(null);
  const itemTweenRef = useRef(null);
  const [renderedDropdownIndex, setRenderedDropdownIndexState] = useState(null);

  const killHideCall = useCallback(() => {
    if (!hideCallRef.current) return;

    hideCallRef.current.kill();
    hideCallRef.current = null;
  }, []);

  const killSwitchTween = useCallback(() => {
    if (!switchTweenRef.current) return;

    switchTweenRef.current.kill();
    switchTweenRef.current = null;
  }, []);

  const killItemTween = useCallback(() => {
    if (!itemTweenRef.current) return;

    itemTweenRef.current.kill();
    itemTweenRef.current = null;
  }, []);

  const getCurrentDropdownItems = useCallback(() => {
    return dropdownItemsRef.current.filter(Boolean);
  }, []);

  const setRenderedDropdownIndex = useCallback((index) => {
    dropdownItemsRef.current = [];
    setRenderedDropdownIndexState(index);
  }, []);

  const showWrapper = useCallback(() => {
    if (!dropdownRef.current) return;

    gsap.set(dropdownRef.current, {
      autoAlpha: 1,
      pointerEvents: "auto",
    });
  }, []);

  const hideWrapper = useCallback(() => {
    if (!dropdownRef.current) return;

    gsap.set(dropdownRef.current, {
      autoAlpha: 0,
      pointerEvents: "none",
    });
  }, []);

  const setNavVisualState = useCallback((activeIndex) => {
    navLinksRef.current.forEach((linkElement, index) => {
      if (!linkElement) return;

      gsap.to(linkElement, {
        color:
          activeIndex !== null && index !== activeIndex
            ? DIMMED_TEXT_COLOR
            : ACTIVE_TEXT_COLOR,
        duration: 0.3,
        overwrite: true,
      });
    });
  }, []);

  const animateTextSwap = useCallback((item, isEntering) => {
    if (!item) return;

    gsap
      .timeline({
        defaults: {
          duration: NAV_TEXT_DURATION,
          ease: "power2.out",
          overwrite: true,
        },
      })
      .to(item.defaultText, { yPercent: isEntering ? -100 : 0 }, 0)
      .to(item.hoverText, { yPercent: isEntering ? 0 : 100 }, 0);
  }, []);

  const initDropdownItemText = useCallback(() => {
    dropdownTextDataRef.current = dropdownItemsRef.current.map((itemElement) => {
      if (!itemElement) return null;

      return {
        defaultText: itemElement.querySelector("[data-default]"),
        hoverText: itemElement.querySelector("[data-hover]"),
      };
    });

    dropdownTextDataRef.current.forEach((item) => {
      if (!item) return;

      gsap.set(item.defaultText, { yPercent: 0 });
      gsap.set(item.hoverText, { yPercent: 100 });
    });
  }, []);

  const animateDropdownItemsIn = useCallback(() => {
    const dropdownItems = getCurrentDropdownItems();
    if (!dropdownItems.length) return;

    killItemTween();
    gsap.killTweensOf(dropdownItems);

    gsap.set(dropdownItems, {
      opacity: 0,
      y: DROPDOWN_ITEM_OFFSET_Y,
      pointerEvents: "none",
    });

    itemTweenRef.current = gsap.timeline({
      overwrite: true,
      onStart: () => {
        gsap.set(dropdownItems, { pointerEvents: "auto" });
      },
    });

    itemTweenRef.current
      .to(
        dropdownItems,
        {
          y: 0,
          duration: 0.6,
          stagger: 0.05,
          ease: "elastic.out(0.9, 0.6)",
        },
        0
      )
      .to(
        dropdownItems,
        {
          opacity: 1,
          duration: 0.4,
          stagger: 0.05,
          ease: "power2.inOut",
        },
        0
      );
  }, [getCurrentDropdownItems, killItemTween]);

  const animateDropdownItemsOut = useCallback(
    (onComplete) => {
      const dropdownItems = getCurrentDropdownItems();

      if (!dropdownItems.length) {
        onComplete?.();
        return;
      }

      killItemTween();
      gsap.killTweensOf(dropdownItems);

      itemTweenRef.current = gsap.timeline({
        overwrite: true,
        onStart: () => {
          gsap.set(dropdownItems, { pointerEvents: "none" });
        },
        onComplete,
      });

      itemTweenRef.current
        .to(
          dropdownItems,
          {
            y: DROPDOWN_ITEM_OFFSET_Y,
            duration: 0.34,
            stagger: 0.04,
            ease: "power2.inOut",
          },
          0
        )
        .to(
          dropdownItems,
          {
            opacity: 0,
            duration: 0.28,
            stagger: 0.04,
            ease: "power2.inOut",
          },
          0
        );
    },
    [getCurrentDropdownItems, killItemTween]
  );

  const closeDropdown = useCallback(() => {
    killHideCall();
    killSwitchTween();

    activeDropdownIndexRef.current = null;

    animateDropdownItemsOut(() => {
      if (activeDropdownIndexRef.current !== null || isPointerInsideDropdownRef.current) {
        return;
      }

      setRenderedDropdownIndex(null);
      hideWrapper();
    });
  }, [animateDropdownItemsOut, hideWrapper, killHideCall, killSwitchTween, setRenderedDropdownIndex]);

  const openDropdownForIndex = useCallback(
    (index) => {
      const menuItem = MENU_ITEMS[index];

      killHideCall();
      killSwitchTween();

      if (!menuItem?.isDropdown) return;

      activeDropdownIndexRef.current = index;
      isPointerInsideDropdownRef.current = false;
      showWrapper();

      if (renderedDropdownIndex === null) {
        setRenderedDropdownIndex(index);
        return;
      }

      if (renderedDropdownIndex === index) {
        const dropdownItems = getCurrentDropdownItems();
        if (!dropdownItems.length) return;

        killItemTween();
        gsap.killTweensOf(dropdownItems);

        itemTweenRef.current = gsap.timeline({
          overwrite: true,
          onStart: () => {
            gsap.set(dropdownItems, { pointerEvents: "auto" });
          },
        });

        itemTweenRef.current
          .to(
            dropdownItems,
            {
              y: 0,
              duration: 0.45,
              stagger: 0.04,
              ease: "elastic.out(0.9, 0.6)",
            },
            0
          )
          .to(
            dropdownItems,
            {
              opacity: 1,
              duration: 0.35,
              stagger: 0.04,
              ease: "power2.inOut",
            },
            0
          );

        return;
      }

      switchTweenRef.current = gsap.delayedCall(0, () => {
        animateDropdownItemsOut(() => {
          if (activeDropdownIndexRef.current === null) return;
          setRenderedDropdownIndex(activeDropdownIndexRef.current);
        });
      });
    },
    [
      animateDropdownItemsOut,
      getCurrentDropdownItems,
      killHideCall,
      killItemTween,
      killSwitchTween,
      setRenderedDropdownIndex,
      showWrapper,
    ]
  );

  const scheduleCloseDropdown = useCallback(() => {
    killHideCall();

    hideCallRef.current = gsap.delayedCall(DROPDOWN_POINTER_DELAY, () => {
      if (isPointerInsideDropdownRef.current) return;
      if (activeDropdownIndexRef.current !== null && MENU_ITEMS[activeDropdownIndexRef.current]?.isDropdown) {
        return;
      }

      closeDropdown();
    });
  }, [closeDropdown, killHideCall]);

  const onHeaderMouseEnter = useCallback(() => {
    killHideCall();
  }, [killHideCall]);

  const onHeaderMouseLeave = useCallback(() => {
    killHideCall();
    killSwitchTween();

    activeDropdownIndexRef.current = null;
    isPointerInsideDropdownRef.current = false;
    setNavVisualState(null);

    animateDropdownItemsOut(() => {
      setRenderedDropdownIndex(null);
      hideWrapper();
    });
  }, [animateDropdownItemsOut, hideWrapper, killHideCall, killSwitchTween, setNavVisualState, setRenderedDropdownIndex]);

  const onNavItemEnter = useCallback(
    (index) => {
      const item = linkDataRef.current[index];
      if (!item) return;

      killHideCall();
      animateTextSwap(item, true);
      setNavVisualState(index);

      if (MENU_ITEMS[index]?.isDropdown) {
        activeDropdownIndexRef.current = index;
        openDropdownForIndex(index);
        return;
      }

      activeDropdownIndexRef.current = null;
      closeDropdown();
    },
    [animateTextSwap, closeDropdown, killHideCall, openDropdownForIndex, setNavVisualState]
  );

  const onNavItemLeave = useCallback(
    (index) => {
      const item = linkDataRef.current[index];
      if (!item) return;

      animateTextSwap(item, false);

      if (MENU_ITEMS[index]?.isDropdown) {
        killHideCall();

        hideCallRef.current = gsap.delayedCall(NAV_POINTER_DELAY, () => {
          if (isPointerInsideDropdownRef.current) return;
          if (activeDropdownIndexRef.current !== index) return;
          closeDropdown();
        });

        return;
      }

      setNavVisualState(null);
    },
    [animateTextSwap, closeDropdown, killHideCall, setNavVisualState]
  );

  const onCtaHover = useCallback((isEntering = true) => {
    const ctaElement = ctaRef.current;
    if (!ctaElement) return;

    const defaultText = ctaElement.querySelector("[data-default]");
    const hoverText = ctaElement.querySelector("[data-hover]");

    gsap
      .timeline({
        defaults: { duration: CTA_DURATION, ease: "power2.out", overwrite: true },
      })
      .to(
        ctaElement,
        { backgroundColor: isEntering ? HOVER_CTA_BACKGROUND : DEFAULT_CTA_BACKGROUND },
        0
      )
      .to(defaultText, { yPercent: isEntering ? -100 : 0 }, 0)
      .to(hoverText, { yPercent: isEntering ? 0 : 100 }, 0);
  }, []);

  const onDropdownMouseEnter = useCallback(() => {
    isPointerInsideDropdownRef.current = true;
    killHideCall();
    showWrapper();
  }, [killHideCall, showWrapper]);

  const onDropdownMouseLeave = useCallback(() => {
    isPointerInsideDropdownRef.current = false;
    scheduleCloseDropdown();
  }, [scheduleCloseDropdown]);

  const onDropdownItemEnter = useCallback(
    (index) => {
      animateTextSwap(dropdownTextDataRef.current[index], true);
    },
    [animateTextSwap]
  );

  const onDropdownItemLeave = useCallback(
    (index) => {
      animateTextSwap(dropdownTextDataRef.current[index], false);
    },
    [animateTextSwap]
  );

  // Effects
  useLayoutEffect(() => {
    const context = gsap.context(() => {
      linkDataRef.current = navLinksRef.current.map((linkElement) => {
        if (!linkElement) return null;

        return {
          defaultText: linkElement.querySelector("[data-default]"),
          hoverText: linkElement.querySelector("[data-hover]"),
        };
      });

      linkDataRef.current.forEach((item) => {
        if (!item) return;

        gsap.set(item.defaultText, { yPercent: 0 });
        gsap.set(item.hoverText, { yPercent: 100 });
      });

      if (ctaRef.current) {
        const defaultText = ctaRef.current.querySelector("[data-default]");
        const hoverText = ctaRef.current.querySelector("[data-hover]");

        gsap.set(defaultText, { yPercent: 0 });
        gsap.set(hoverText, { yPercent: 100 });
      }

      hideWrapper();
    });

    return () => context.revert();
  }, [hideWrapper]);

  useLayoutEffect(() => {
    if (renderedDropdownIndex === null) return;

    initDropdownItemText();
    animateDropdownItemsIn();
  }, [animateDropdownItemsIn, initDropdownItemText, renderedDropdownIndex]);

  useEffect(() => {
    return () => {
      killHideCall();
      killSwitchTween();
      killItemTween();
    };
  }, [killHideCall, killItemTween, killSwitchTween]);

  // Derived values
  const dropdownItems = MENU_ITEMS[renderedDropdownIndex]?.dropdown || [];

  return (
    <div
      ref={navWrapRef}
      onMouseEnter={onHeaderMouseEnter}
      onMouseLeave={onHeaderMouseLeave}
      className="absolute top-[1vw] right-[2vw] rounded-md bg-[#363737] max-md:hidden"
    >
      <div className="relative flex h-full w-full items-center gap-[1.5vw] p-[0.3vw] pl-[1vw]">
        <div className="flex h-full items-center gap-[1.5vw]">
          {MENU_ITEMS.map((item, index) => (
            <Link
              key={item.name}
              ref={(element) => {
                navLinksRef.current[index] = element;
              }}
              href={item.href}
              className="relative flex items-center overflow-hidden py-[0.5vw] uppercase"
              onMouseEnter={() => onNavItemEnter(index)}
              onMouseLeave={() => onNavItemLeave(index)}
            >
              <div className="relative overflow-hidden">
                <span data-default className="flex items-center">
                  {item.name}
                  {item.isDropdown && <ChevronDown className="ml-1 h-[1vw] w-[1vw]" />}
                </span>

                <span
                  data-hover
                  className="absolute inset-0 flex items-center justify-center"
                >
                  <span className="flex items-center">
                    {item.name}
                    {item.isDropdown && <ChevronUp className="ml-1 h-[1vw] w-[1vw]" />}
                  </span>
                </span>
              </div>
            </Link>
          ))}
        </div>

        <Link
          ref={ctaRef}
          href="#"
          className="relative overflow-hidden rounded-sm bg-white px-[0.5vw] py-[0.5vw] text-black"
          onMouseEnter={() => onCtaHover(true)}
          onMouseLeave={() => onCtaHover(false)}
        >
          <span data-default className="block">
            BUILT W/ HYPERIUX
          </span>
          <span
            data-hover
            className="absolute inset-0 flex items-center justify-center text-white"
          >
            BUILT W/ HYPERIUX
          </span>
        </Link>

        <div
          ref={dropdownRef}
          onMouseEnter={onDropdownMouseEnter}
          onMouseLeave={onDropdownMouseLeave}
          className="absolute top-[calc(100%-.5vw)] left-0 h-fit w-full pt-[1.3vw]"
        >
          <div className="space-y-[0.4vw]">
            {dropdownItems.map((item, index) => (
              <div
                key={`${renderedDropdownIndex}-${item.title}`}
                ref={(element) => {
                  dropdownItemsRef.current[index] = element;
                }}
                className="link-btns"
              >
                <Link
                  href={item.href}
                  onMouseEnter={() => onDropdownItemEnter(index)}
                  onMouseLeave={() => onDropdownItemLeave(index)}
                  className="flex items-center justify-between rounded-md bg-[#363737] p-[0.4vw] text-white transition-all duration-400 hover:scale-[1.02] hover:bg-white hover:text-black!"
                >
                  <div className="flex items-center gap-[1.5vw]">
                    <div className="size-[5vw] overflow-hidden rounded-md">
                      <div className="relative h-full w-full">
                        <Image
                          src={item.img}
                          alt={item.title}
                          width={500}
                          height={500}
                          className="h-full w-full object-cover"
                        />
                        <div
                          className="absolute inset-0"
                          style={{
                            background: IMAGE_TINT,
                            mixBlendMode: "multiply",
                            pointerEvents: "none",
                          }}
                        />
                      </div>
                    </div>

                    <div className="relative overflow-hidden uppercase">
                      <span data-default className="block">
                        {item.title}
                      </span>
                      <span data-hover className="absolute inset-0 flex items-center">
                        {item.title}
                      </span>
                    </div>
                  </div>

                  <ChevronRight className="mr-[2vw] h-[1vw] w-[1vw]" />
                </Link>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useCallback, useEffect, useRef } from "react";
import {
  motion,
  useAnimationFrame,
  useMotionValue,
  useScroll,
  useSpring,
  useTransform,
  useVelocity,
} from "motion/react";

// Custom wrap function
const wrap = (min, max, value) => {
  const range = max - min
  return ((((value - min) % range) + range) % range) + min
}

const MarqueeAlongSvgPath = ({
  children,
  className,

  // Path defaults
  path,

  pathId,
  preserveAspectRatio = "xMidYMid meet",
  showPath = false,

  // SVG defaults
  width = "100%",

  height = "100%",
  viewBox = "0 0 100 100",

  // Marquee defaults
  baseVelocity = 5,

  direction = "normal",
  easing,
  slowdownOnHover = false,
  slowDownFactor = 0.3,
  slowDownSpringConfig = { damping: 50, stiffness: 400 },

  // Scroll defaults
  useScrollVelocity = false,

  scrollAwareDirection = false,
  scrollSpringConfig = { damping: 50, stiffness: 400 },
  scrollContainer,

  // Items repetition
  repeat = 3,

  // Drag defaults
  draggable = false,

  dragSensitivity = 0.2,
  dragVelocityDecay = 0.96,
  dragAwareDirection = false,
  grabCursor = false,

  // Z-index defaults
  enableRollingZIndex = true,

  // Base z-index value
  zIndexBase = 1,

  // Range of z-index values to use
  zIndexRange = 10,

  cssVariableInterpolation = [],

  // Responsive defaults
  responsive = false
}) => {
  const container = useRef(null)
  const marqueeContainerRef = useRef(null)
  const baseOffset = useMotionValue(0)

  const pathRef = useRef(null)

  const itemRefs = useRef(new Map())

  // Responsive scaling using direct DOM manipulation (no re-renders)
  useEffect(() => {
    if (!responsive) return

    const [, , vbWidth, vbHeight] = viewBox.split(" ").map(Number)
    const originalWidth = vbWidth || 100
    const originalHeight = vbHeight || 100

    const updateScale = () => {
      const wrapper = container.current
      const marqueeContainer = marqueeContainerRef.current
      if (!wrapper || !marqueeContainer) return

      const wrapperWidth = wrapper.clientWidth
      const wrapperHeight = wrapper.clientHeight

      const scaleX = wrapperWidth / originalWidth
      const scaleY = wrapperHeight / originalHeight
      const scale = Math.min(scaleX, scaleY)

      // Calculate the scaled dimensions
      const scaledWidth = originalWidth * scale
      const scaledHeight = originalHeight * scale

      // Center the marquee container within the wrapper
      const offsetX = (wrapperWidth - scaledWidth) / 2
      const offsetY = (wrapperHeight - scaledHeight) / 2

      // Set fixed dimensions on the container
      marqueeContainer.style.width = `${originalWidth}px`
      marqueeContainer.style.height = `${originalHeight}px`

      // Apply scale and position to center
      marqueeContainer.style.transform = `translate(${offsetX}px, ${offsetY}px) scale(${scale})`
      marqueeContainer.style.transformOrigin = "top left"
    }

    updateScale()
    window.addEventListener("resize", updateScale)
    return () => window.removeEventListener("resize", updateScale);
  }, [responsive, viewBox])

  // Create an array of items outside of the render function
  const items = React.useMemo(() => {
    const childrenArray = React.Children.toArray(children)

    return childrenArray.flatMap((child, childIndex) =>
      Array.from({ length: repeat }, (_, repeatIndex) => {
        const itemIndex = repeatIndex * childrenArray.length + childIndex
        const key = `${childIndex}-${repeatIndex}`
        return {
          child,
          childIndex,
          repeatIndex,
          itemIndex,
          key,
        }
      }));
  }, [children, repeat])

  // Function to calculate z-index based on offset distance
  const calculateZIndex = useCallback((offsetDistance) => {
    if (!enableRollingZIndex) {
      return undefined
    }

    // Simple progress-based z-index
    const normalizedDistance = offsetDistance / 100
    return Math.floor(zIndexBase + normalizedDistance * zIndexRange);
  }, [enableRollingZIndex, zIndexBase, zIndexRange])

  // Generate a random ID for the path if not provided
  const id = pathId || `marquee-path-${Math.random().toString(36).substring(7)}`

  // Scroll tracking
 const { scrollY } = useScroll({
  container: scrollContainer || undefined,
})

  const scrollVelocity = useVelocity(scrollY)
  const smoothVelocity = useSpring(scrollVelocity, scrollSpringConfig)

  // Hover and drag state tracking
  const isHovered = useRef(false)
  const isDragging = useRef(false)
  const dragVelocity = useRef(0)

  // Direction factor for changing direction based on scroll or drag
  const directionFactor = useRef(direction === "normal" ? 1 : -1)

  // Motion values for animation
  const hoverFactorValue = useMotionValue(1)
  const defaultVelocity = useMotionValue(1)
  const smoothHoverFactor = useSpring(hoverFactorValue, slowDownSpringConfig)

  // Transform scroll velocity into a factor that affects marquee speed
  const velocityFactor = useTransform(
    useScrollVelocity ? smoothVelocity : defaultVelocity,
    [0, 1000],
    [0, 5],
    { clamp: false }
  )

  // Animation frame handler
  useAnimationFrame((_, delta) => {
    if (isDragging.current && draggable) {
      baseOffset.set(baseOffset.get() + dragVelocity.current)

      // Add decay to dragVelocity
      dragVelocity.current *= 0.9

      // Stop completely if velocity is very small
      if (Math.abs(dragVelocity.current) < 0.01) {
        dragVelocity.current = 0
      }

      return
    }

    // Update hover factor
    if (isHovered.current) {
      hoverFactorValue.set(slowdownOnHover ? slowDownFactor : 1)
    } else {
      hoverFactorValue.set(1)
    }

    // Calculate regular movement
    let moveBy =
      directionFactor.current *
      baseVelocity *
      (delta / 1000) *
      smoothHoverFactor.get()

    // Adjust movement based on scroll velocity if scrollAwareDirection is enabled
    if (scrollAwareDirection && !isDragging.current) {
      if (velocityFactor.get() < 0) {
        directionFactor.current = -1
      } else if (velocityFactor.get() > 0) {
        directionFactor.current = 1
      }
    }

    moveBy += directionFactor.current * moveBy * velocityFactor.get()

    if (draggable) {
      moveBy += dragVelocity.current

      // Update direction based on drag direction if dragAwareDirection is true
      if (dragAwareDirection && Math.abs(dragVelocity.current) > 0.1) {
        directionFactor.current = Math.sign(dragVelocity.current)
      }

