 case 1:
 return { x: 20, y: -20, rotateX: 0, rotateZ: 2, rotateY: 0, scale: 0.9, opacity: 1, zIndex: 10 };
 case 2:
 return { x: 35, y: -40, rotateX: 0, rotateZ: 4, rotateY: 0, scale: 0.83, opacity: 0.9, zIndex: 8 };
 case -1:
 return { x: -20, y: -20, rotateX: 0, rotateZ: -2, rotateY: 0, scale: 0.9, opacity: 1, zIndex: 10 };
 case -2:
 return { x: -35, y: -40, rotateX: 0, rotateZ: -4, rotateY: 0, scale: 0.83, opacity: 0.9, zIndex: 8 };
