'use client'

import { useState, useEffect } from'react';
import { motion } from'framer-motion';

function useMousePosition() {
 const [mousePosition, setMousePosition] = useState({ x: null, y: null });

 useEffect(() => {
 const updateMousePosition = (e) => {
 setMousePosition({ x: e.clientX, y: e.clientY });
 };
 window.addEventListener('mousemove', updateMousePosition);
 return () => window.removeEventListener('mousemove', updateMousePosition);
 }, []);

 return mousePosition;
}

function useIsPointerFine() {
 const [isPointerFine, setIsPointerFine] = useState(false);

 useEffect(() => {
 const mq = window.matchMedia('(pointer: fine)');
 setIsPointerFine(mq.matches);
 const handler = (e) => setIsPointerFine(e.matches);
 mq.addEventListener('change', handler);
 return () => mq.removeEventListener('change', handler);
 }, []);

 return isPointerFine;
}

export default function CircleReveal({
 textColor ='#111',
 Text ="We craft emotionally intelligent user experiences that are adored globally!",
 revealText ="A visual designer — with skills that haven't been replaced by A.I",
 circleColorBg ='#E76F2E',
 RevealedTextColor ='#fefefe'
}) {
 const [isHovered, setIsHovered] = useState(false);
 const { x, y } = useMousePosition();
 const isPointerFine = useIsPointerFine();

 const [smoothPos, setSmoothPos] = useState(null);

 const size = isHovered ? 500 : 40;

 useEffect(() => {
 if (!isPointerFine) return;

 let animationFrame;

 const lerp = (start, end, factor) => start + (end - start) * factor;

 const animate = () => {
 setSmoothPos((prev) => {
 if (x === null || y === null) return prev;
 if (prev === null) return { x, y };
 return {
 x: lerp(prev.x, x, 0.15),
 y: lerp(prev.y, y, 0.15),
 };
 });

 animationFrame = requestAnimationFrame(animate);
 };

 animate();

 return () => cancelAnimationFrame(animationFrame);
 }, [x, y, isPointerFine]);

 return (
 <section className="w-screen h-screen flex items-center justify-center text-[7vw] text-center px-[5vw] bg-[#fefefe] relative overflow-hidden">

 {/* ── Masked layer — desktop/mouse only, hidden until first mouse move ── */}
 {isPointerFine && smoothPos !== null && (
 <motion.div
 className="absolute inset-0 flex items-center justify-center z-10"
 style={{
 WebkitMaskImage:'radial-gradient(circle at center, black 50%, transparent 51%)',
 WebkitMaskRepeat:'no-repeat',
 }}
 animate={{
 WebkitMaskPosition: `${smoothPos.x - size / 2}px ${smoothPos.y - size / 2}px`,
 WebkitMaskSize: `${size}px ${size}px`,
 }}
 transition={{ type:'tween', ease:'backOut', duration: 0.5 }}
 >
 <div className="absolute inset-0" style={{ backgroundColor: circleColorBg }} />

 <h2
 className="relative z-10 leading-tight cursor-default select-none"
 style={{ color: RevealedTextColor }}
 onMouseEnter={() => setIsHovered(true)}
 onMouseLeave={() => setIsHovered(false)}
 >
 {revealText}
 </h2>
 </motion.div>
 )}


 <div className="relative z-0">
 <h2
 className="leading-tight select-none"
 style={{ color: textColor }}
 >
 {Text}
 </h2>
 </div>

 </section>
 );
}

'use client'

import React, { useEffect, useRef, useState } from'react'
import gsap from'gsap'
import ScrollTrigger from'gsap/dist/ScrollTrigger'

gsap.registerPlugin(ScrollTrigger)

export default function HomeAero({
 text,
 colors = {
 color1:'#7f7de4',
 color2:'#f79694',
 color3:'#f5dd94',
 },
 enableEntryAnimation = true,
 textColor ='#000000',
}) {
 const container = useRef(null)
 const aeroText = useRef(null)
 const maskedText = useRef(null)
 const [isDesktop, setIsDesktop] = useState(false)
 const circleTrackers = useRef([
 { x: 0, y: 0 }, // color1
 { x: 0, y: 0 }, // color2
 { x: 0, y: 0 }, // color3
 ])

 useEffect(() => {
 const checkWidth = () => {
 setIsDesktop(window.innerWidth >= 1025)
 }

 checkWidth() // initial check

 window.addEventListener('resize', checkWidth)

 return () => window.removeEventListener('resize', checkWidth)
}, [])

 useEffect(() => {
 const el = container.current
 const maskEl = maskedText.current
 if (!el || !maskEl || !isDesktop) {
 gsap.killTweensOf(circleTrackers.current)
 return
 }

 const syncMaskVars = () => {
 maskEl.style.setProperty('--x-color1', `${circleTrackers.current[0].x}px`)
 maskEl.style.setProperty('--y-color1', `${circleTrackers.current[0].y}px`)
 maskEl.style.setProperty('--x-color2', `${circleTrackers.current[1].x}px`)
 maskEl.style.setProperty('--y-color2', `${circleTrackers.current[1].y}px`)
 maskEl.style.setProperty('--x-color3', `${circleTrackers.current[2].x}px`)
 maskEl.style.setProperty('--y-color3', `${circleTrackers.current[2].y}px`)
 }

 const initRect = maskEl.getBoundingClientRect()
 const cx = initRect.width / 2
 const cy = initRect.height / 2
 circleTrackers.current.forEach((item) => {
 item.x = cx
 item.y = cy
 })
 syncMaskVars()

 const onMove = (evt) => {
 const rect = maskEl.getBoundingClientRect()
 const localX = evt.clientX - rect.left
 const localY = evt.clientY - rect.top

 gsap.to(circleTrackers.current, {
 x: localX,
 y: localY,
 duration: 0.5,
 ease:'power1.out',
 stagger: -0.1,
 overwrite:'auto',
 onUpdate: syncMaskVars,
 })
 }

 el.addEventListener('mousemove', onMove)
 return () => {
 el.removeEventListener('mousemove', onMove)
 gsap.killTweensOf(circleTrackers.current)
 }
 }, [isDesktop])

 useEffect(() => {
 if (!enableEntryAnimation) return

 const ctx = gsap.context(() => {
 gsap.from(aeroText.current, {
 scrollTrigger: {
 trigger: container.current,
 start:'top 60%',
 },
 opacity: 0,
 yPercent: 320,
 skewY: 30,
 duration: 3,
 ease:'expo.out',
 })
 }, container)

 return () => ctx.revert()
 }, [enableEntryAnimation])

 return (
 <section
 ref={container}
 data-cursor-color="#000"
 data-cursor-size="0px"
 className="relative w-screen h-screen overflow-hidden bg-[#ececec] tablet:h-[70vh]"
 >
 <div className="relative flex h-full w-full items-center justify-center overflow-hidden">
 <div
 ref={aeroText}
 className="relative w-[70%] tablet:w-[80%]"
 >
 <p
 className="text-center font-heading text-[6vw] font-medium max-md:text-[8vw] max-sm:text-[10vw]"
 style={{ color: textColor }}
 >
 {text}
 </p>

 {isDesktop && (
 <p
 ref={maskedText}
 aria-hidden
 className="pointer-events-none absolute inset-0 text-center font-heading text-[6vw] font-medium text-transparent [background-clip:text] [-webkit-background-clip:text] [-webkit-text-fill-color:transparent] max-[1024px]:text-[8vw] max-[540px]:text-[10vw]"
 style={{
'--x-color1':'50%',
'--y-color1':'50%',
'--x-color2':'50%',
'--y-color2':'50%',
'--x-color3':'50%',
'--y-color3':'50%',
 backgroundImage: `
 radial-gradient(circle 135px at var(--x-color3) var(--y-color3), ${colors.color3} 0 99%, transparent 100%),
 radial-gradient(circle 220px at var(--x-color2) var(--y-color2), ${colors.color2} 0 99%, transparent 100%),
 radial-gradient(circle 325px at var(--x-color1) var(--y-color1), ${colors.color1} 0 99%, transparent 100%)
 `,
 }}
 >
 {text}
 </p>
 )}
 </div>
 </div>
 </section>
 )
}

import { useMemo, useEffect } from"react";
import { Effect } from"postprocessing";
import { Uniform, Vector2 } from"three";

/**
 * Both shaders share the same blur logic, but the output differs:
 * - classic: pure blur, no frosted white overlay
 * - frosted: blur + white, semi-transparent veil toward edges
 */

const classicBlurFragmentShader = /* glsl */ `
uniform float uBlurStrength;
uniform float uBlurStart;
uniform vec2 uResolution;

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {
 vec2 center = uv - 0.5;
 float dist = length(center);

 float blurAmount = smoothstep(uBlurStart, 0.75, dist) * uBlurStrength;

 if (blurAmount < 0.001) {
 outputColor = inputColor;
 return;
 }

 float aspect = uResolution.x / uResolution.y;
 vec2 texelSize = vec2(1.0 / uResolution.x, 1.0 / uResolution.y);

 const int TAPS = 12;
 vec2 offsets[12];
 offsets[0] = vec2(-0.326, -0.406);
 offsets[1] = vec2(-0.840, -0.074);
 offsets[2] = vec2(-0.696, 0.457);
 offsets[3] = vec2(-0.203, 0.621);
 offsets[4] = vec2( 0.962, -0.195);
 offsets[5] = vec2( 0.473, -0.480);
 offsets[6] = vec2( 0.519, 0.767);
 offsets[7] = vec2( 0.185, -0.893);
 offsets[8] = vec2( 0.507, 0.064);
 offsets[9] = vec2( 0.896, 0.412);
 offsets[10] = vec2(-0.322, -0.933);
 offsets[11] = vec2(-0.792, -0.598);

 float radius = blurAmount * 12.0;

 vec4 blurred = inputColor;
 float totalWeight = 1.0;

 for (int i = 0; i < TAPS; i++) {
 vec2 offset = offsets[i] * radius * texelSize;
 vec4 s = texture2D(inputBuffer, uv + offset);
 blurred += s;
 totalWeight += 1.0;
 }

 blurred /= totalWeight;

 outputColor = blurred;
}
`;

const frostedBlurFragmentShader = /* glsl */ `
uniform float uBlurStrength;
uniform float uBlurStart;
uniform vec2 uResolution;

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {
 vec2 center = uv - 0.5;
 float dist = length(center);

 float blurAmount = smoothstep(uBlurStart, 0.75, dist) * uBlurStrength;

 if (blurAmount < 0.001) {
 outputColor = inputColor;
 return;
 }

 float aspect = uResolution.x / uResolution.y;
 vec2 texelSize = vec2(1.0 / uResolution.x, 1.0 / uResolution.y);

 const int TAPS = 12;
 vec2 offsets[12];
 offsets[0] = vec2(-0.326, -0.406);
 offsets[1] = vec2(-0.840, -0.074);
 offsets[2] = vec2(-0.696, 0.457);
 offsets[3] = vec2(-0.203, 0.621);
 offsets[4] = vec2( 0.962, -0.195);
 offsets[5] = vec2( 0.473, -0.480);
 offsets[6] = vec2( 0.519, 0.767);
 offsets[7] = vec2( 0.185, -0.893);
 offsets[8] = vec2( 0.507, 0.064);
 offsets[9] = vec2( 0.896, 0.412);
 offsets[10] = vec2(-0.322, -0.933);
 offsets[11] = vec2(-0.792, -0.598);

 float radius = blurAmount * 12.0;

 vec4 blurred = inputColor;
 float totalWeight = 1.0;

 for (int i = 0; i < TAPS; i++) {
 vec2 offset = offsets[i] * radius * texelSize;
 vec4 s = texture2D(inputBuffer, uv + offset);
 blurred += s;
 totalWeight += 1.0;
 }

 blurred /= totalWeight;

 // White, semi-transparent veil for frosted-edge effect.
 vec3 white = vec3(1.0, 1.0, 1.0);
 float veilAlpha = 0.4 * blurAmount; // Max 0.4 opacity at the strongest blur

 // Correct GLSL: mix(vec3, vec3, float)
 vec3 outRgb = mix(blurred.rgb, white, veilAlpha);
 float outAlpha = blurred.a;

 outputColor = vec4(outRgb, outAlpha);
}
`;

/**
 * EdgeBlurEffect component
 * @param {'classic'|'frosted'} blurType Use"frosted" (default) for white edge,"classic" for pure blur
 * @param {number} blurStrength
 * @param {number} blurStart
 */
class EdgeBlurEffectImpl extends Effect {
 constructor({
 blurStrength = 1.0,
 blurStart = 0.25,
 resolution = [1280, 720],
 frag = frostedBlurFragmentShader,
 } = {}) {
 const uniforms = new Map([
 ["uBlurStrength", new Uniform(blurStrength)],
 ["uBlurStart", new Uniform(blurStart)],
 ["uResolution", new Uniform(new Vector2(resolution[0], resolution[1]))],
 ]);
 super("EdgeBlurEffect", frag, { uniforms });
 }

 setResolution(width, height) {
 const uRes = this.uniforms.get("uResolution");
 if (uRes) uRes.value.set(width, height);
 }

 update(renderer) {
 if (renderer && renderer.getSize) {
 const size = renderer.getSize(new Vector2());
 this.setResolution(size.x, size.y);
 }
 }
}

export default function EdgeBlurEffect({
 blurType ="classic", //"frosted" |"classic"
 blurStrength = 1.0,
 blurStart = 0.25,
}) {
 const frag =
 blurType ==="classic"
 ? classicBlurFragmentShader
 : frostedBlurFragmentShader;

 const effect = useMemo(() => {
 let width = 1280,
 height = 720;
 if (typeof window !=="undefined") {
 width = window.innerWidth;
 height = window.innerHeight;
 }
 return new EdgeBlurEffectImpl({
 blurStrength,
 blurStart,
 resolution: [width, height],
 frag,
 });
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [blurStrength, blurStart, frag]);

 useEffect(() => {
 if (typeof window ==="undefined") return;
 const update = () => effect.setResolution(window.innerWidth, window.innerHeight);
 window.addEventListener("resize", update);
 update();
 return () => window.removeEventListener("resize", update);
 }, [effect]);

 return <primitive object={effect} dispose={null} />;
}

