 <NoiseDietherShader
 // imageSrc={imageSrc}
 noiseColor="#1825AA"
 style={{ width:'100%', height:'100%', position:'relative', zIndex: 1 }}
 pixelSize={pixelSize}
 patternDensity={patternDensity}
 fluidRadius={fluidRadius}
