        <div className="absolute right-4 top-1/2 -translate-y-1/2 text-sm text-neutral-400">
          {totalCount} effects
        </div>
      )}
    </div>
  );
}

export function GlobalSearch({ effects = [], externalOpen = false }) {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState("");
  const inputRef = useRef(null);
  const router = useRouter();
  const lenis = useLenis();

  // Handle lenis scroll pause
  useEffect(() => {
    if (isOpen) {
      lenis?.stop();
    } else {
      lenis?.start();
    }
  }, [isOpen, lenis]);

  // Open when externalOpen changes to true
  useEffect(() => {
    if (externalOpen) {
      setIsOpen(true);
    }
  }, [externalOpen]);

  // Handle keyboard shortcut
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setIsOpen(true);
      }
      if (e.key === "Escape") {
        setIsOpen(false);
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Focus input when modal opens
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  const filteredEffects = effects.filter((effect) => {
    const q = query.toLowerCase();
    const cats = effect.categories?.length ? effect.categories : [effect.category];
    return (
      effect.name.toLowerCase().includes(q) ||
      effect.title.toLowerCase().includes(q) ||
      cats.some((c) => c?.toLowerCase().includes(q))
    );
  });

  const handleSelect = (effect) => {
    router.push(getEffectHref(effect));
    setIsOpen(false);
    setQuery("");
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[20vh]">
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity"
        onClick={() => setIsOpen(false)}
      />

      {/* Modal */}
      <div className="relative w-full max-w-xl mx-4 bg-neutral-950/90 backdrop-blur-xl rounded-xl  overflow-hidden border border-neutral-800/60 flex flex-col h-113  ring-1 ring-white/5">
        {/* Search input */}
        <div className="flex items-center gap-3 px-4 py-4 border-b border-neutral-800/50 bg-black/20">
          <svg className="w-5 h-5 text-neutral-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search effects..."
            className="flex-1 bg-transparent text-white placeholder:text-neutral-500 text-base sm:text-lg focus:outline-none"
          />
          <kbd className="hidden sm:inline-flex px-2 py-1 bg-neutral-900 border border-neutral-800 rounded text-xs text-neutral-400 font-medium">
            ESC
          </kbd>
        </div>

        {/* Results */}
        <div className="flex-1 overflow-y-auto" data-lenis-prevent="true">
          {filteredEffects.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center text-neutral-500 px-4">
              <svg className="w-12 h-12 mb-4 text-neutral-700" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <p>No effects found for &quot;<span className="text-neutral-300">{query}</span>&quot;</p>
              <p className="text-sm mt-1 text-neutral-600">Try searching with a different term.</p>
            </div>
          ) : (
            <div className="p-2 space-y-1">
              {filteredEffects.map((effect) => (
                <button
                  key={effect.name}
                  onClick={() => handleSelect(effect)}
                  className="w-full flex items-center cursor-pointer gap-4 px-3 py-3 rounded-xl hover:bg-neutral-800/50 text-left transition-all duration-200 group"
                >
                  <div className="w-10 h-10 bg-neutral-900 border border-neutral-800/60 rounded-lg flex items-center justify-center text-neutral-400 group-hover:text-white group-hover:border-neutral-600 transition-colors">
                    {effect.category?.[0]?.toUpperCase() || "E"}
                  </div>
                  <div className="flex-1">
                    <div className="font-medium text-neutral-200 group-hover:text-white transition-colors">{effect.title}</div>
                    <div className="text-xs text-neutral-500 capitalize mt-0.5 group-hover:text-neutral-400 transition-colors">
                      {(effect.categories?.length ? effect.categories : [effect.category]).join(", ")}
                    </div>
                  </div>
                  <svg className="w-5 h-5 text-neutral-600 opacity-0 group-hover:opacity-100 group-hover:text-neutral-400 transition-all transform -translate-x-2 group-hover:translate-x-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                  </svg>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client'

import { TransitionRouter } from 'next-transition-router'
import React, { useEffect, useRef, useState } from 'react'
import gsap from 'gsap'
import Image from 'next/image'

export default function ChessGridTransition({ children, enableContentShift = false }) {
  const wrapperRef = useRef(null)
  const gridRef = useRef(null)
  const bgRef = useRef(null)

  const [mounted, setMounted] = useState(false)
  const [isMobile, setIsMobile] = useState(false)
  const [isTablet, setIsTablet] = useState(false)

  const cols = 8
  const desktopRows = 4
  const mobileRows = 9
  const tabletRows = 10
  const overlap = 2

  useEffect(() => {
    const updateViewport = () => {
      const width = window.innerWidth
      setIsMobile(width <= 639)
      setIsTablet(width > 639 && width <= 1025)
    }

    updateViewport()
    window.addEventListener('resize', updateViewport)
    return () => window.removeEventListener('resize', updateViewport)
  }, [])

  const rows = isMobile ? mobileRows : isTablet ? tabletRows : desktopRows

  const getRowCells = (cells, rowIndex) => {
    const rowCells = []
    for (let col = 0; col < cols; col++) {
      rowCells.push(cells[rowIndex * cols + col])
    }
    return rowCells
  }

  const buildAnimation = (tl, cells, direction = 1) => {
    const rowsArr = Array.from({ length: rows }, (_, i) => i)

    rowsArr.forEach((rowIndex, rowOrderIndex) => {
      const rowCells = getRowCells(cells, rowIndex)

      rowCells.forEach((cell, colIndex) => {
        const delay = rowOrderIndex * 0.1 + colIndex * 0.1

        if (direction === 1) {
          const translateAmount = (cols - colIndex + 1) * 100

          tl.fromTo(
            cell,
            { xPercent: translateAmount },
            {
              xPercent: 0,
              duration: 0.8,
              ease: 'power2.out',
            },
            delay
          )
        } else {
          tl.to(
            cell,
            {
              xPercent: -(colIndex + 2) * 100,
              duration: 0.8,
              ease: 'power2.in',
            },
            delay
          )
        }
      })
    })
  }

  useEffect(() => {
    const cells = gridRef.current.children

    Array.from(cells).forEach((cell, i) => {
      const colIndex = i % cols
      gsap.set(cell, { xPercent: -(colIndex + 2) * 100 })
    })

    setMounted(true)
  }, [rows])

  const totalCells = cols * rows

  return (
    <TransitionRouter
      auto
      leave={(next) => {
        const cells = gridRef.current.children
        const tl = gsap.timeline({ onComplete: next })

        tl.fromTo(
          [wrapperRef.current, bgRef.current],
          { opacity: 1, y: 0 },
          { opacity: 0, duration: 0.8, y: -50 },
          0
        )

        buildAnimation(tl, cells, 1)
        return () => tl.kill()
      }}
      enter={(next) => {
        const cells = gridRef.current.children
        const tl = gsap.timeline({ onComplete: next })

        tl.fromTo(
          [wrapperRef.current, bgRef.current],
          { opacity: 0, y: 50 },
          { opacity: 1, duration: 0.8, delay: 1, y: 0, clearProps: 'all' },
          0
        )

        buildAnimation(tl, cells, -1)
        return () => tl.kill()
      }}
    >
      <div
        ref={gridRef}
        className={`h-screen w-screen fixed top-0 left-0 z-999 pointer-events-none flex flex-wrap overflow-hidden ${
          mounted ? 'opacity-100' : 'opacity-0'
        }`}
      >
        {Array.from({ length: totalCells }).map((_, i) => {
          const colIndex = i % cols
          const rowIndex = Math.floor(i / cols)

          return (
            <span
              key={i}
              className='bg-[#ff5f00] absolute shrink-0'
              style={{
                width: `calc((100vw / ${cols}) * ${isMobile ? 1.6 : 1} + ${overlap}px)`,
                height: `calc(100vh / ${rows} + ${overlap}px)`,
                left: `calc(${colIndex} * (100vw / ${cols}) * ${isMobile ? 1.6 : 1} - ${overlap / 2}px)`,
                top: `calc(${rowIndex} * (100vh / ${rows}) - ${overlap / 2}px)`,
              }}
            ></span>
          )
        })}
      </div>

      <div className='h-full w-full relative z-2'>
        <div ref={wrapperRef} className='h-full w-full'>
          {children}
        </div>
      </div>


    </TransitionRouter>
  )
}

'use client'

import { TransitionRouter } from 'next-transition-router'
import React, { useEffect, useRef, useState } from 'react'
import gsap from 'gsap'

export default function FlipTransition({
  children,
  duration = 0.9,
  bgColor = '#ff5f00',
}) {
  const wrapperRef = useRef(null)
  const exitOverlayRef = useRef(null)
  const enterOverlayRef = useRef(null)
  const boxesRef = useRef(null)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    // EXIT overlay: hidden — folded off-screen to the left (-90deg from bottom-left)
    gsap.set(exitOverlayRef.current, {
      rotation: -90,
      transformOrigin: 'bottom left',
    })

    // ENTER overlay: hidden — folded off-screen (-90deg from bottom-right)
    gsap.set(enterOverlayRef.current, {
      rotation: -90,
      transformOrigin: 'bottom right',
    })

    // Boxes hidden initially
    gsap.set(boxesRef.current.children, { scaleY: 0 })

    setMounted(true)
  }, [])

  return (
    <TransitionRouter
      auto
      leave={(next) => {
        document.documentElement.style.overflow = 'hidden'
        const tl = gsap.timeline({ onComplete: next })

        // Fade + shift old content out
        tl.to(wrapperRef.current, {
          opacity: 0,
          y: -40,
          duration: 0.5,
          ease: 'power2.in',
        }, 0)

        // Keep enter overlay hidden during exit
        tl.set(enterOverlayRef.current, { rotation: -90, transformOrigin: 'bottom right' }, 0)

        // EXIT: bottom-left origin, -90deg → 0deg
        tl.fromTo(
          exitOverlayRef.current,
          { rotation: -90, transformOrigin: 'bottom left' },
          { rotation: 0, transformOrigin: 'bottom left', duration, ease: 'power3.inOut' },
          0
        )

        // Boxes scale up from bottom once overlay is mostly covering screen
        tl.to(boxesRef.current.children, {
          scaleY: 1,
          transformOrigin: 'bottom',
          duration: 0.4,
          stagger: 0.08,
          ease: 'power2.out',
        }, 0.5)

        return () => tl.kill()
      }}
      enter={(next) => {
        const tl = gsap.timeline({
          onComplete: () => {
            document.documentElement.style.overflow = ''
            next()
          },
        })

        // Snap exit overlay away
        tl.set(exitOverlayRef.current, { rotation: -90, transformOrigin: 'bottom left' }, 0)

        // Snap enter overlay flat (covering screen)
        tl.set(enterOverlayRef.current, { rotation: 0, transformOrigin: 'bottom right' }, 0)

        // Boxes scale down from top first
        tl.to(boxesRef.current.children, {
          scaleY: 0,
          transformOrigin: 'top',
          duration: 0.35,
          stagger: 0.06,
          ease: 'power2.in',
        }, 0)

        // Fade new content in
        tl.fromTo(wrapperRef.current,
          { opacity: 0, y: 40 },
          { opacity: 1, y: 0, duration: 0.6, ease: 'power2.out', clearProps: "all" },
          0.45
        )

        // ENTER: bottom-right origin, 0deg → +90deg (clockwise)
        tl.fromTo(
          enterOverlayRef.current,
          { rotation: 0, transformOrigin: 'bottom right' },
          { rotation: 90, transformOrigin: 'bottom right', duration, ease: 'power3.inOut' },
          0.3
        )

        return () => tl.kill()
      }}
    >
      {/* EXIT overlay — bottom-left anchor */}
      <div
        ref={exitOverlayRef}
        className="fixed bottom-0 left-0 pointer-events-none"
        style={{
          width: '150vmax',
          height: '150vmax',
          transformOrigin: 'bottom left',
          zIndex: 9999,
          opacity: mounted ? 1 : 0,
          backgroundColor: bgColor,
          overflow: 'hidden',
        }}
      />

      {/* ENTER overlay — bottom-right anchor */}
      <div
        ref={enterOverlayRef}
        className="fixed bottom-0 right-0 pointer-events-none"
        style={{
          width: '150vmax',
          height: '150vmax',
          transformOrigin: 'bottom right',
          zIndex: 9998,
          opacity: mounted ? 1 : 0,
          backgroundColor: bgColor,
          overflow: 'hidden',
        }}
      />

      {/* Boxes — fixed to screen center, above both overlays */}
      <div
        className="fixed inset-0 flex items-center justify-center pointer-events-none"
        style={{ zIndex: 10000 }}
      >
        <div ref={boxesRef} className="flex gap-2">
          <span className="block w-4 h-7 bg-black scale-y-0" />
          <span className="block w-4 h-7 bg-black scale-y-0" />
          <span className="block w-4 h-7 bg-black scale-y-0" />
          <span className="block w-4 h-7 bg-black scale-y-0" />
        </div>
      </div>

      {/* Page content */}
      <div ref={wrapperRef} className="relative w-full min-h-screen" style={{ zIndex: 2 }}>
        {children}
      </div>
    </TransitionRouter>
  )
}

'use client'

import { TransitionRouter } from 'next-transition-router'
import { useEffect, useRef } from 'react'
import gsap from 'gsap'

const DURATION_LEAVE = 0.6
const DURATION_ENTER = 0.4
const COLOR = '#111111'

// Generate a seeded deterministic shuffle for consistent pixel order per session
function generatePixelOrder(cols, rows, seed = 42) {
  const total = cols * rows
  const indices = Array.from({ length: total }, (_, i) => i)
  // Simple seeded LCG shuffle
  let s = seed
  const rand = () => {
    s = (s * 1664525 + 1013904223) & 0xffffffff
    return (s >>> 0) / 0xffffffff
  }
  for (let i = total - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1))
    ;[indices[i], indices[j]] = [indices[j], indices[i]]
  }
  return indices
}

function easeInOutQuad(t) {
  return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t
}

function easeInQuart(t) {
  return t * t * t * t
}

function easeOutQuart(t) {
  return 1 - (--t) * t * t * t
}

export default function PixelRandom({
  children,
  color = COLOR,
  durationLeave = DURATION_LEAVE,
  durationEnter = DURATION_ENTER,
}) {
  const wrapperRef = useRef(null)
  const canvasRef = useRef(null)
  const tweenRef = useRef(null)
  const stateRef = useRef({ progress: 0 })
  const pixelOrderRef = useRef(null)

  const getCols = () => (window.innerWidth < 640 ? 12 : 30)
  const getRows = () => (window.innerWidth < 640 ? 22 : 20)

  const resizeCanvas = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    const dpr = window.devicePixelRatio || 1
    const w = window.innerWidth
    const h = window.innerHeight
    canvas.width = Math.ceil(w * dpr)
    canvas.height = Math.ceil(h * dpr)
    canvas.style.width = `${w}px`
    canvas.style.height = `${h}px`
    const ctx = canvas.getContext('2d')
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)

    // Regenerate pixel order on resize
    const cols = getCols()
    const rows = getRows()
    pixelOrderRef.current = generatePixelOrder(cols, rows)
  }

  // Draw the pixel grid at a given progress (0 = empty, 1 = full)
  // isEnter = true means we're revealing (dissolving away pixels)
  const drawPixels = (canvas, progress, isEnter) => {
    if (!canvas) return

    const ctx = canvas.getContext('2d')
    const w = canvas.clientWidth
    const h = canvas.clientHeight
    const cols = getCols()
    const rows = getRows()

    const cellW = w / cols
    const cellH = h / rows
    const total = cols * rows

    ctx.clearRect(0, 0, w, h)
    ctx.fillStyle = color

    const order = pixelOrderRef.current
    if (!order || order.length !== total) {
      pixelOrderRef.current = generatePixelOrder(cols, rows)
    }

    // Each pixel gets a staggered trigger based on its position in the random order
    // Pixels appear/disappear at different rates to create organic spread effect
    for (let i = 0; i < total; i++) {
      const idx = order ? order[i] : i
      const c = idx % cols
      const r = Math.floor(idx / cols)

      // Stagger: earlier pixels in the order appear first
      // Use a wave-like stagger with slight clustering
      const normalizedPos = i / total

      // Add slight randomness via pixel position hash to break up uniformity
      const posHash = ((c * 7 + r * 13) % 23) / 23
      const staggerStart = normalizedPos * 0.92 + posHash * 0.04
      const staggerEnd = staggerStart + 0.08

      let local = (progress - staggerStart) / (staggerEnd - staggerStart)
      local = Math.max(0, Math.min(1, local))

      const easedLocal = isEnter ? easeOutQuart(local) : easeInOutQuad(local)
      const opacity = isEnter ? 1 - easedLocal : easedLocal

      if (opacity < 0.01) continue

      const x1 = Math.floor(c * cellW)
      const x2 = Math.ceil((c + 1) * cellW)
      const y1 = Math.floor(r * cellH)
      const y2 = Math.ceil((r + 1) * cellH)

      ctx.globalAlpha = opacity
      ctx.fillRect(x1, y1, x2 - x1, y2 - y1)
    }
    ctx.globalAlpha = 1
  }

  const animatePixels = ({ from, to, duration, isEnter, onComplete }) => {
    const canvas = canvasRef.current
    if (!canvas) {
      onComplete()
      return null
    }

    canvas.style.opacity = '1'
    stateRef.current.progress = from
    drawPixels(canvas, from, isEnter)

    tweenRef.current?.kill()

    const tween = gsap.to(stateRef.current, {
      progress: to,
      duration,
      ease: 'none',
      onUpdate: () => drawPixels(canvas, stateRef.current.progress, isEnter),
      onComplete: () => {
        drawPixels(canvas, to, isEnter)
        if (isEnter) canvas.style.opacity = '0'
        onComplete()
      },
    })

    tweenRef.current = tween
    return tween
  }

  useEffect(() => {
    resizeCanvas()
    window.addEventListener('resize', resizeCanvas)
    return () => {
      window.removeEventListener('resize', resizeCanvas)
      tweenRef.current?.kill()
    }
  }, [])

  return (
    <TransitionRouter
      auto
      leave={(next) => {
        const timeline = gsap.timeline({ onComplete: next })

        timeline.fromTo(wrapperRef.current, { opacity: 1, y: 0 }, { opacity: 0, duration: durationLeave, y: -50 }, 0)

        const tween = animatePixels({
          from: 0,
          to: 1,
          duration: durationLeave,
          isEnter: false,
          onComplete: () => {},
        })

        return () => {
          timeline.kill()
          tween?.kill()
        }
      }}
      enter={(next) => {
        const timeline = gsap.timeline({ onComplete: next })

        timeline.fromTo(
          wrapperRef.current,
          { opacity: 0, y: 50 },
          {
            opacity: 1,
            duration: durationEnter,
            delay: durationLeave,
            y: 0,
            clearProps: 'all',
          },
          0
        )

        const tween = animatePixels({
          from: 0,
          to: 1,
          duration: durationEnter,
          isEnter: true,
          onComplete: () => {},
        })

        return () => {
          timeline.kill()
          tween?.kill()
        }
      }}
    >
      <canvas
        ref={canvasRef}
        className="pointer-events-none fixed top-0 left-0 z-999 h-screen w-screen opacity-0"
      />

      <div className="relative z-2 h-full w-full">
        <div ref={wrapperRef} className="h-full w-full">
          {children}
        </div>
      </div>
    </TransitionRouter>
  )
}
